/**
 * Unit tests for {@link PotentialCreator#overrideMode(JsonCreator.Mode)}
 * and related functionality added in issue #4584.
 */
public class PotentialCreatorOverrideModeTest {

    @Test
    public void testOverrideModeChangesCreatorMode() {
        // Create a mock AnnotatedWithParams for testing
        AnnotatedWithParams mockCreator = Mockito.mock(AnnotatedWithParams.class);
        Mockito.when(mockCreator.getParameterCount()).thenReturn(0);

        // Create PotentialCreator with DEFAULT mode
        PotentialCreator creator = new PotentialCreator(mockCreator, JsonCreator.Mode.DEFAULT);

        // Verify initial mode
        assertEquals(JsonCreator.Mode.DEFAULT, creator.creatorMode());

        // Override mode to DELEGATING
        creator.overrideMode(JsonCreator.Mode.DELEGATING);

        // Verify mode was changed
        assertEquals(JsonCreator.Mode.DELEGATING, creator.creatorMode());
    }

    @Test
    public void testOverrideModeReturnsThisForChaining() {
        // Create a mock AnnotatedWithParams for testing
        AnnotatedWithParams mockCreator = Mockito.mock(AnnotatedWithParams.class);
        Mockito.when(mockCreator.getParameterCount()).thenReturn(0);

        PotentialCreator creator = new PotentialCreator(mockCreator, JsonCreator.Mode.DEFAULT);

        // Verify overrideMode returns this for method chaining
        PotentialCreator result = creator.overrideMode(JsonCreator.Mode.PROPERTIES);

        assertSame(creator, result, "overrideMode should return this for chaining");
    }

    @Test
    public void testOverrideModeWithMultipleChanges() {
        // Create a mock AnnotatedWithParams for testing
        AnnotatedWithParams mockCreator = Mockito.mock(AnnotatedWithParams.class);
        Mockito.when(mockCreator.getParameterCount()).thenReturn(0);

        PotentialCreator creator = new PotentialCreator(mockCreator, null);

        // Initial mode should be DEFAULT when null is passed
        assertEquals(JsonCreator.Mode.DEFAULT, creator.creatorMode());

        // Chain multiple mode changes
        creator.overrideMode(JsonCreator.Mode.DELEGATING)
               .overrideMode(JsonCreator.Mode.PROPERTIES)
               .overrideMode(JsonCreator.Mode.DISABLED);

        // Verify final mode
        assertEquals(JsonCreator.Mode.DISABLED, creator.creatorMode());
    }

    @Test
    public void testOverrideModeWithNullConstructorMode() {
        // Create a mock AnnotatedWithParams for testing
        AnnotatedWithParams mockCreator = Mockito.mock(AnnotatedWithParams.class);
        Mockito.when(mockCreator.getParameterCount()).thenReturn(0);

        // Create with null mode (should default to DEFAULT)
        PotentialCreator creator = new PotentialCreator(mockCreator, null);

        // Verify isAnnotated is false when mode was null
        assertFalse(creator.isAnnotated());

        // Override mode
        creator.overrideMode(JsonCreator.Mode.DELEGATING);

        // Verify mode was changed
        assertEquals(JsonCreator.Mode.DELEGATING, creator.creatorMode());
    }

    @Test
    public void testOverrideModeWithAnnotatedConstructor() {
        // Create a mock AnnotatedWithParams for testing
        AnnotatedWithParams mockCreator = Mockito.mock(AnnotatedWithParams.class);
        Mockito.when(mockCreator.getParameterCount()).thenReturn(0);

        // Create with explicit annotation
        PotentialCreator creator = new PotentialCreator(mockCreator, JsonCreator.Mode.PROPERTIES);

        // Verify isAnnotated is true when mode was provided
        assertTrue(creator.isAnnotated());

        // Override mode to DELEGATING
        creator.overrideMode(JsonCreator.Mode.DELEGATING);

        // Verify mode was changed but isAnnotated remains true
        assertEquals(JsonCreator.Mode.DELEGATING, creator.creatorMode());
        assertTrue(creator.isAnnotated());
    }

    @Test
    public void testCreatorModeOrDefaultAfterOverride() {
        // Create a mock AnnotatedWithParams for testing
        AnnotatedWithParams mockCreator = Mockito.mock(AnnotatedWithParams.class);
        Mockito.when(mockCreator.getParameterCount()).thenReturn(0);

        PotentialCreator creator = new PotentialCreator(mockCreator, null);

        // creatorModeOrDefault should return DEFAULT when mode is null
        assertEquals(JsonCreator.Mode.DEFAULT, creator.creatorModeOrDefault());

        // Override to DELEGATING
        creator.overrideMode(JsonCreator.Mode.DELEGATING);

        // creatorModeOrDefault should now return DELEGATING
        assertEquals(JsonCreator.Mode.DELEGATING, creator.creatorModeOrDefault());
    }

    @Test
    public void testOverrideModeChainingWithIntrospectParamNames() {
        // Create a mock AnnotatedWithParams for testing
        AnnotatedWithParams mockCreator = Mockito.mock(AnnotatedWithParams.class);
        Mockito.when(mockCreator.getParameterCount()).thenReturn(0);

        MapperConfig<?> mockConfig = Mockito.mock(MapperConfig.class);

        PotentialCreator creator = new PotentialCreator(mockCreator, null);

        // Chain overrideMode with introspectParamNames
        creator.overrideMode(JsonCreator.Mode.DELEGATING)
               .introspectParamNames(mockConfig);

        // Verify mode was set
        assertEquals(JsonCreator.Mode.DELEGATING, creator.creatorMode());
    }

    @Test
    public void testOverrideModeAllEnumValues() {
        // Create a mock AnnotatedWithParams for testing
        AnnotatedWithParams mockCreator = Mockito.mock(AnnotatedWithParams.class);
        Mockito.when(mockCreator.getParameterCount()).thenReturn(0);

        // Test all JsonCreator.Mode enum values
        for (JsonCreator.Mode mode : JsonCreator.Mode.values()) {
            PotentialCreator creator = new PotentialCreator(mockCreator, JsonCreator.Mode.DEFAULT);
            creator.overrideMode(mode);
            assertEquals(mode, creator.creatorMode(), 
                "Failed for mode: " + mode);
        }
    }
}

