package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.exc.InvalidFormatException;
import org.junit.Test;

import static org.junit.Assert.*;

public class EnumDeser4481Test {

    enum Color {
        RED, BLUE
    }

    static class BeanWithOverride {
        @JsonFormat(without = JsonFormat.Feature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)
        public Color color;
    }

    static class BeanWithEnable {
        @JsonFormat(with = JsonFormat.Feature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)
        public Color color;
    }

    static class BeanWithoutAnnotation {
        public Color color;
    }

    @Test
    public void testFieldAnnotationOverridesGlobalEnabled() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        // Field annotation says WITHOUT, so should throw exception even though global is enabled
        // This is the main bug fix for issue #4481
        try {
            mapper.readValue("{\"color\":\"WHITE\"}", BeanWithOverride.class);
            fail("Should have thrown InvalidFormatException");
        } catch (InvalidFormatException e) {
            // Expected - field annotation overrides global setting
