package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

/**
 * Test class to verify that @JsonSetter(nulls = Nulls.SKIP) works correctly
 * for both field-based and setter-based properties.
 * 
 * This test validates the fix for the bug where null values were not being
 * skipped properly during deserialization when Nulls.SKIP was configured.
 */
public class NullsSkipDeserTest {

    /**
     * Test bean with field-based property using @JsonSetter(nulls = Nulls.SKIP)
     */
    static class FieldBean {
        @JsonSetter(nulls = Nulls.SKIP)
        public List<String> list1 = new ArrayList<>();
    }

    /**
     * Test bean with setter-based property using @JsonSetter(nulls = Nulls.SKIP)
     */
    static class SetterBean {
        private List<String> list1 = new ArrayList<>();

        @JsonSetter(nulls = Nulls.SKIP)
        public void setList1(List<String> list1) {
            this.list1 = list1;
        }

        public List<String> getList1() {
            return list1;
        }
    }

    /**
     * Inner class for nested structure testing
     */
    static class Inner {
        public String field1;

        public Inner() {}
    }

    /**
     * Middle class with @JsonSetter(nulls = Nulls.SKIP) for nested testing
     */
    static class Middle {
        @JsonSetter(nulls = Nulls.SKIP)
        public List<Inner> list1 = new ArrayList<>();
    }

    /**
     * Outer class for nested structure testing
     */
    static class Outer {
        public List<Middle> list1;
    }

    /**
     * Test that field-based properties with Nulls.SKIP preserve initialized values
     * when null is encountered during deserialization.
     * 
     * This tests the FieldProperty.set() and FieldProperty.setAndReturn() methods
     * which were fixed in the patch to check _skipNulls before setting the field.
     */
    @Test
    public void testFieldPropertyNullsSkip() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test with null value - should skip and keep initialized list
        String json = "{\"list1\": null}";
        FieldBean bean = mapper.readValue(json, FieldBean.class);

        assertNotNull("List should not be null when Nulls.SKIP is used", bean.list1);
        assertTrue("List should be empty (initialized value preserved)", bean.list1.isEmpty());
    }

    /**
     * Test that setter-based properties with Nulls.SKIP preserve initialized values
     * when null is encountered during deserialization.
     * 
     * This tests the MethodProperty.set() and MethodProperty.setAndReturn() methods
     * which were fixed in the patch to check _skipNulls before invoking the setter.
     */
    @Test
    public void testSetterPropertyNullsSkip() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test with null value - should skip and keep initialized list
        String json = "{\"list1\": null}";
        SetterBean bean = mapper.readValue(json, SetterBean.class);

        assertNotNull("List should not be null when Nulls.SKIP is used", bean.getList1());
        assertTrue("List should be empty (initialized value preserved)", bean.getList1().isEmpty());
    }

    /**
     * Test nested structure with Nulls.SKIP to verify the fix works in complex scenarios.
     * 
     * This reproduces the exact scenario from the issue where:
     * - There is a nested object structure (Outer -> Middle -> Inner)
     * - The JSON input contains a null value for a field with @JsonSetter(nulls = Nulls.SKIP)
     * - The field is initialized with a default value
     * 
     * Before the fix, the null would overwrite the initialized list.
     * After the fix, the null is skipped and the initialized list is preserved.
     */
    @Test
    public void testNestedStructureNullsSkip() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test nested structure with null value as described in the issue
        String json = "{\"list1\": [{\"list1\": null}]}";
        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull("Outer list1 should not be null", outer.list1);
        assertEquals("Outer list1 should have 1 element", 1, outer.list1.size());

        Middle middle = outer.list1.get(0);
        assertNotNull("Middle list1 should not be null when Nulls.SKIP is used", middle.list1);
        assertTrue("Middle list1 should be empty (initialized value preserved)", middle.list1.isEmpty());
    }

    /**
     * Test that non-null values still work correctly with Nulls.SKIP configuration.
     * 
     * This ensures the fix doesn't break normal deserialization behavior.
     */
    @Test
    public void testNonNullValueStillWorks() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test with non-null value - should still work normally
        String json = "{\"list1\": [\"item1\", \"item2\"]}";
        FieldBean bean = mapper.readValue(json, FieldBean.class);

        assertNotNull("List should not be null", bean.list1);
        assertEquals("List should have 2 elements", 2, bean.list1.size());
        assertEquals("First element", "item1", bean.list1.get(0));
        assertEquals("Second element", "item2", bean.list1.get(1));
    }

    /**
     * Test that Nulls.SKIP works correctly when field order varies in JSON.
     * 
     * This verifies the fix addresses the issue where field order could cause
     * null values to be processed after construction, overriding initialized values.
     */
    @Test
    public void testFieldOrderIndependence() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test with different field orders
        String json1 = "{\"list1\": null}";
        String json2 = "{\"list1\": [\"item1\"]}";

        FieldBean bean1 = mapper.readValue(json1, FieldBean.class);
        FieldBean bean2 = mapper.readValue(json2, FieldBean.class);

        // First bean should have empty list (null skipped)
        assertNotNull("Bean1 list should not be null", bean1.list1);
        assertTrue("Bean1 list should be empty", bean1.list1.isEmpty());

        // Second bean should have the provided list
        assertNotNull("Bean2 list should not be null", bean2.list1);
        assertEquals("Bean2 list should have 1 element", 1, bean2.list1.size());
    }
}

