package com.fasterxml.jackson.databind.ext;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import javax.xml.namespace.QName;

import static org.junit.Assert.*;

/**
 * Test class for verifying the fix of issue #4450:
 * Empty QName deserialized as `null`
 * 
 * This test ensures that when deserializing an empty JSON string "" to QName,
 * the result is an empty QName instance (QName.valueOf("")), not null.
 */
public class QNameEmptyStringDeserTest {

    private final ObjectMapper MAPPER = new ObjectMapper();

    @Test
    public void testEmptyQNameDeserialization() throws Exception {
        // Deserialize empty JSON string to QName
        QName qname = MAPPER.readValue("\"\"", QName.class);

        // Verify that the result is not null
        assertNotNull("Empty string should deserialize to empty QName, not null", qname);

        // Verify that the QName has an empty local part
        assertTrue("QName local part should be empty", qname.getLocalPart().isEmpty());

        // Verify it matches QName.valueOf("")
        QName expected = QName.valueOf("");
        assertEquals("Deserialized QName should match QName.valueOf(\"\")", expected, qname);
    }

    @Test
    public void testNonEmptyQNameDeserialization() throws Exception {
        // Verify that non-empty QName strings still work correctly
        QName qname = MAPPER.readValue("\"{http://example.com}local\"", QName.class);

        assertNotNull("Non-empty QName string should deserialize successfully", qname);
        assertEquals("local", qname.getLocalPart());
        assertEquals("http://example.com", qname.getNamespaceURI());
    }

    @Test
    public void testSimpleQNameDeserialization() throws Exception {
        // Verify simple QName (no namespace) still works
        QName qname = MAPPER.readValue("\"simpleName\"", QName.class);

        assertNotNull("Simple QName string should deserialize successfully", qname);
        assertEquals("simpleName", qname.getLocalPart());
    }
}

