package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Test for Issue #4309: {@code @JsonSetter(nulls=...)} handling of {@code Collection} {@code null} values
 * during deserialization with {@code READ_UNKNOWN_ENUM_VALUES_AS_NULL} and {@code FAIL_ON_INVALID_SUBTYPE}.
 *
 * Verifies that when {@code Nulls.SKIP} is configured for collection contents, null values resulting from
 * unknown enum values (treated as null) are skipped rather than added to the collection.
 */
public class Issue4309Test {

    public enum Enum4309 {
        A, B
    }

    public static class BeanWithAnnotation {
        @JsonSetter(contentNulls = Nulls.SKIP)
        public List<Enum4309> values;
    }

    public static class BeanWithGlobalConfig {
        public List<Enum4309> values;
    }

    /**
     * Test that unknown enum values in a JSON array are skipped when contentNulls is set to SKIP.
     * This tests the general collection deserialization path.
     */
    @Test
    public void testSkipNullsFromUnknownEnumWithAnnotation() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);

        String json = "{\"values\": [\"A\", \"UNKNOWN\"]}";
        BeanWithAnnotation bean = mapper.readValue(json, BeanWithAnnotation.class);

        assertNotNull(bean.values);
        // "UNKNOWN" is treated as null due to READ_UNKNOWN_ENUM_VALUES_AS_NULL
        // Then it should be skipped due to contentNulls = SKIP
        assertEquals(1, bean.values.size());
        assertEquals(Enum4309.A, bean.values.get(0));
    }

    /**
     * Test that unknown enum value as a single value (ACCEPT_SINGLE_VALUE_AS_ARRAY) is skipped.
     * This specifically tests the handleNonArray method path which was modified in the patch.
     */
    @Test
    public void testSkipNullsFromUnknownEnumSingleValueWithAnnotation() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);
        mapper.enable(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY);

        String json = "{\"values\": \"UNKNOWN\"}";
        BeanWithAnnotation bean = mapper.readValue(json, BeanWithAnnotation.class);

        assertNotNull(bean.values);
        // "UNKNOWN" -> null -> skipped by handleNonArray logic
        assertEquals(0, bean.values.size());
    }

    /**
     * Test that global configuration for contentNulls SKIP works correctly with unknown enums.
     */
    @Test
    public void testSkipNullsFromUnknownEnumWithGlobalConfig() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);
        mapper.setDefaultSetterInfo(JsonSetter.Value.forContentNulls(Nulls.SKIP));

        String json = "{\"values\": [\"A\", \"UNKNOWN\"]}";
        BeanWithGlobalConfig bean = mapper.readValue(json, BeanWithGlobalConfig.class);

        assertNotNull(bean.values);
        assertEquals(1, bean.values.size());
        assertEquals(Enum4309.A, bean.values.get(0));
    }
}

