package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.node.NullNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.node.TextNode;
import org.junit.Test;

import static org.junit.Assert.*;

public class JsonNodeWithPropertyTest {

    private final JsonNodeFactory nodeFactory = JsonNodeFactory.instance;

    @Test
    public void testWithObjectPropertyOnBaseJsonNode() {
        // Base JsonNode implementation should throw UnsupportedOperationException
        JsonNode node = nodeFactory.nullNode();
        try {
            node.withObjectProperty("test");
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("ObjectNode"));
            assertTrue(e.getMessage().contains("withObjectProperty"));
        }
    }

    @Test
    public void testWithArrayPropertyOnBaseJsonNode() {
        // Base JsonNode implementation should throw UnsupportedOperationException
        JsonNode node = nodeFactory.nullNode();
        try {
            node.withArrayProperty("test");
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("ObjectNode"));
            assertTrue(e.getMessage().contains("withArrayProperty"));
        }
    }

    @Test
    public void testWithObjectPropertyCreatesNewNode() {
        ObjectNode objectNode = nodeFactory.objectNode();

        // Property doesn't exist - should create new ObjectNode
        ObjectNode result = objectNode.withObjectProperty("newProp");

        assertNotNull(result);
        assertTrue(result.isObject());
        assertTrue(objectNode.has("newProp"));
        assertSame(result, objectNode.get("newProp"));
    }

    @Test
    public void testWithObjectPropertyReturnsExistingNode() {
        ObjectNode objectNode = nodeFactory.objectNode();
        ObjectNode existingNode = nodeFactory.objectNode();
        objectNode.set("existingProp", existingNode);

        // Property exists with ObjectNode - should return existing node
        ObjectNode result = objectNode.withObjectProperty("existingProp");

        assertSame(existingNode, result);
    }

    @Test
    public void testWithObjectPropertyReplacesNullNode() {
        ObjectNode objectNode = nodeFactory.objectNode();
        objectNode.set("nullProp", nodeFactory.nullNode());

        // Property exists with NullNode - should create new ObjectNode
        ObjectNode result = objectNode.withObjectProperty("nullProp");

        assertNotNull(result);
        assertTrue(result.isObject());
        assertSame(result, objectNode.get("nullProp"));
        assertFalse(objectNode.get("nullProp").isNull());
    }

    @Test
    public void testWithObjectPropertyThrowsOnWrongType() {
        ObjectNode objectNode = nodeFactory.objectNode();
        objectNode.set("textProp", nodeFactory.textNode("text"));

        // Property exists with wrong type - should throw exception
        try {
            objectNode.withObjectProperty("textProp");
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("ObjectNode"));
        }
    }

    @Test
    public void testWithArrayPropertyCreatesNewNode() {
        ObjectNode objectNode = nodeFactory.objectNode();

        // Property doesn't exist - should create new ArrayNode
        ArrayNode result = objectNode.withArrayProperty("newProp");

        assertNotNull(result);
        assertTrue(result.isArray());
        assertTrue(objectNode.has("newProp"));
        assertSame(result, objectNode.get("newProp"));
    }

