    public void testWithArrayPropertyReturnsExistingNode() {
        ObjectNode objectNode = nodeFactory.objectNode();
        ArrayNode existingNode = nodeFactory.arrayNode();
        objectNode.set("existingProp", existingNode);

        // Property exists with ArrayNode - should return existing node
        ArrayNode result = objectNode.withArrayProperty("existingProp");

        assertSame(existingNode, result);
    }

    @Test
    public void testWithArrayPropertyReplacesNullNode() {
        ObjectNode objectNode = nodeFactory.objectNode();
        objectNode.set("nullProp", nodeFactory.nullNode());

        // Property exists with NullNode - should create new ArrayNode
        ArrayNode result = objectNode.withArrayProperty("nullProp");

