        objectNode.set("textProp", nodeFactory.textNode("text"));

        // Property exists with wrong type - should throw exception
        try {
            objectNode.withArrayProperty("textProp");
            fail("Expected UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue(e.getMessage().contains("Cannot replace"));
            assertTrue(e.getMessage().contains("ArrayNode"));
        }
    }

    @Test
    public void testWithObjectPropertyChaining() {
        ObjectNode objectNode = nodeFactory.objectNode();

        // Test chaining - create nested structure
        ObjectNode level1 = objectNode.withObjectProperty("level1");
        ObjectNode level2 = level1.withObjectProperty("level2");

        level2.put("value", "test");

        assertEquals("test", objectNode.path("level1").path("level2").path("value").asText());
    }

    @Test
    public void testWithArrayPropertyChaining() {
        ObjectNode objectNode = nodeFactory.objectNode();

        // Test chaining - add to array
        ArrayNode array = objectNode.withArrayProperty("items");
        array.addObject().put("name", "item1");
