        // Create both object and array properties
        ObjectNode objProp = objectNode.withObjectProperty("objProp");
        ArrayNode arrProp = objectNode.withArrayProperty("arrProp");

        objProp.put("key", "value");
        arrProp.add("item1");
        arrProp.add("item2");

