package com.fasterxml.jackson.databind.node;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * Unit tests for the withArrayProperty(String) method added in patch #4095.
 * Tests cover the three main scenarios:
 * 1. Creating new ArrayNode when property doesn't exist or is null
 * 2. Returning existing ArrayNode when property already exists as ArrayNode
 * 3. Throwing exception when property exists but is wrong type
 * 4. Throwing exception when called on non-ObjectNode
 */
public class ObjectNodeWithArrayPropertyTest {

    private final ObjectMapper mapper = new ObjectMapper();

    @Test
    public void testWithArrayPropertyCreatesNewWhenPropertyDoesNotExist() {
        ObjectNode objectNode = mapper.createObjectNode();
        ArrayNode arrayNode = objectNode.withArrayProperty("newArray");

        assertNotNull(arrayNode);
        assertTrue(arrayNode.isArray());
        assertTrue(arrayNode.isEmpty());
        assertTrue(objectNode.has("newArray"));
        assertSame(arrayNode, objectNode.get("newArray"));
    }

    @Test
    public void testWithArrayPropertyCreatesNewWhenPropertyIsNull() {
        ObjectNode objectNode = mapper.createObjectNode();
        objectNode.putNull("nullArray");

        ArrayNode arrayNode = objectNode.withArrayProperty("nullArray");

        assertNotNull(arrayNode);
        assertTrue(arrayNode.isArray());
        assertTrue(arrayNode.isEmpty());
        assertTrue(objectNode.get("nullArray").isArray());
        assertSame(arrayNode, objectNode.get("nullArray"));
    }

    @Test
    public void testWithArrayPropertyReturnsExistingArrayNode() {
        ObjectNode objectNode = mapper.createObjectNode();
        ArrayNode existingArray = objectNode.putArray("existingArray");
        existingArray.add("item1");
        existingArray.add("item2");

        ArrayNode returnedArray = objectNode.withArrayProperty("existingArray");

        assertNotNull(returnedArray);
        assertSame(existingArray, returnedArray);
        assertEquals(2, returnedArray.size());
        assertEquals("item1", returnedArray.get(0).asText());
        assertEquals("item2", returnedArray.get(1).asText());
    }

    @Test
    public void testWithArrayPropertyThrowsExceptionWhenWrongType() {
        ObjectNode objectNode = mapper.createObjectNode();
        objectNode.put("textProperty", "some text");

        UnsupportedOperationException exception = assertThrows(
            UnsupportedOperationException.class,
            () -> objectNode.withArrayProperty("textProperty")
        );

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("Cannot replace"));
        assertTrue(exception.getMessage().contains("ArrayNode"));
        assertTrue(exception.getMessage().contains("textProperty"));
        assertTrue(exception.getMessage().contains("OverwriteMode.NULLS"));
    }

    @Test
    public void testWithArrayPropertyThrowsExceptionWhenPropertyIsObjectNode() {
        ObjectNode objectNode = mapper.createObjectNode();
        objectNode.putObject("objectProperty").put("key", "value");

        UnsupportedOperationException exception = assertThrows(
            UnsupportedOperationException.class,
            () -> objectNode.withArrayProperty("objectProperty")
        );

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("Cannot replace"));
        assertTrue(exception.getMessage().contains("ArrayNode"));
    }

    @Test
    public void testWithArrayPropertyOnNonObjectNodeThrowsException() {
        JsonNode arrayNode = mapper.createArrayNode();

        UnsupportedOperationException exception = assertThrows(
            UnsupportedOperationException.class,
            () -> arrayNode.withArrayProperty("property")
        );

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("not of type `ObjectNode`"));
        assertTrue(exception.getMessage().contains("withArrayProperty"));
    }

    @Test
    public void testWithArrayPropertyOnTextNodeThrowsException() {
        JsonNode textNode = mapper.getNodeFactory().textNode("some text");

        UnsupportedOperationException exception = assertThrows(
            UnsupportedOperationException.class,
            () -> textNode.withArrayProperty("property")
        );

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("not of type `ObjectNode`"));
    }

    @Test
    public void testWithArrayPropertyOnNullNodeThrowsException() {
        JsonNode nullNode = mapper.getNodeFactory().nullNode();

        UnsupportedOperationException exception = assertThrows(
            UnsupportedOperationException.class,
            () -> nullNode.withArrayProperty("property")
        );

        assertNotNull(exception.getMessage());
        assertTrue(exception.getMessage().contains("not of type `ObjectNode`"));
    }

    @Test
    public void testWithArrayPropertyMultipleCallsReturnSameInstance() {
        ObjectNode objectNode = mapper.createObjectNode();

        ArrayNode firstCall = objectNode.withArrayProperty("multiCall");
        firstCall.add("first");

        ArrayNode secondCall = objectNode.withArrayProperty("multiCall");

        assertSame(firstCall, secondCall);
        assertEquals(1, secondCall.size());
        assertEquals("first", secondCall.get(0).asText());
    }

    @Test
    public void testWithArrayPropertyWithNumericPropertyName() {
        ObjectNode objectNode = mapper.createObjectNode();
        ArrayNode arrayNode = objectNode.withArrayProperty("123");

        assertNotNull(arrayNode);
        assertTrue(arrayNode.isArray());
        assertTrue(objectNode.has("123"));
    }

    @Test
    public void testWithArrayPropertyWithSpecialCharacters() {
        ObjectNode objectNode = mapper.createObjectNode();
        ArrayNode arrayNode = objectNode.withArrayProperty("special-key_name");

        assertNotNull(arrayNode);
        assertTrue(arrayNode.isArray());
        assertTrue(objectNode.has("special-key_name"));
    }

    @Test
    public void testWithArrayPropertyDoesNotAffectOtherProperties() {
        ObjectNode objectNode = mapper.createObjectNode();
        objectNode.put("existingProp", "value");
        objectNode.putObject("existingObject").put("key", "val");

        ArrayNode arrayNode = objectNode.withArrayProperty("newArray");

        assertEquals(3, objectNode.size());
        assertEquals("value", objectNode.get("existingProp").asText());
        assertTrue(objectNode.get("existingObject").isObject());
        assertTrue(arrayNode.isArray());
    }
}

