package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import org.junit.Test;

import java.util.Optional;
import java.util.OptionalInt;
import java.util.OptionalLong;
import java.util.OptionalDouble;

import static org.junit.Assert.*;

public class BeanUtilTest {

    @Test
    public void testCheckUnsupportedTypeForOptional() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test Optional<T>
        JavaType optionalType = typeFactory.constructType(Optional.class);
        String result = BeanUtil.checkUnsupportedType(optionalType);
        assertNotNull("Optional should be detected as unsupported type", result);
        assertTrue("Message should mention Java 8 optional", result.contains("Java 8 optional"));
        assertTrue("Message should mention jackson-datatype-jdk8 module", result.contains("jackson-datatype-jdk8"));

        // Test OptionalInt
        JavaType optionalIntType = typeFactory.constructType(OptionalInt.class);
        result = BeanUtil.checkUnsupportedType(optionalIntType);
        assertNotNull("OptionalInt should be detected as unsupported type", result);
        assertTrue("Message should mention Java 8 optional", result.contains("Java 8 optional"));
        assertTrue("Message should mention jackson-datatype-jdk8 module", result.contains("jackson-datatype-jdk8"));

        // Test OptionalLong
        JavaType optionalLongType = typeFactory.constructType(OptionalLong.class);
        result = BeanUtil.checkUnsupportedType(optionalLongType);
        assertNotNull("OptionalLong should be detected as unsupported type", result);
        assertTrue("Message should mention Java 8 optional", result.contains("Java 8 optional"));
        assertTrue("Message should mention jackson-datatype-jdk8 module", result.contains("jackson-datatype-jdk8"));

        // Test OptionalDouble
        JavaType optionalDoubleType = typeFactory.constructType(OptionalDouble.class);
        result = BeanUtil.checkUnsupportedType(optionalDoubleType);
        assertNotNull("OptionalDouble should be detected as unsupported type", result);
        assertTrue("Message should mention Java 8 optional", result.contains("Java 8 optional"));
        assertTrue("Message should mention jackson-datatype-jdk8 module", result.contains("jackson-datatype-jdk8"));
    }

    @Test
    public void testIsJava8OptionalClass() {
        // Test Optional<T>
        assertTrue("Optional should be recognized as Java 8 Optional class", 
                BeanUtil.isJava8OptionalClass(Optional.class));

        // Test OptionalInt
        assertTrue("OptionalInt should be recognized as Java 8 Optional class", 
                BeanUtil.isJava8OptionalClass(OptionalInt.class));

        // Test OptionalLong
        assertTrue("OptionalLong should be recognized as Java 8 Optional class", 
                BeanUtil.isJava8OptionalClass(OptionalLong.class));

        // Test OptionalDouble
        assertTrue("OptionalDouble should be recognized as Java 8 Optional class", 
                BeanUtil.isJava8OptionalClass(OptionalDouble.class));

        // Test non-optional classes
        assertFalse("String should not be recognized as Java 8 Optional class", 
                BeanUtil.isJava8OptionalClass(String.class));
        assertFalse("Integer should not be recognized as Java 8 Optional class", 
                BeanUtil.isJava8OptionalClass(Integer.class));
        assertFalse("java.time classes should not be recognized as Java 8 Optional class", 
                BeanUtil.isJava8OptionalClass(java.time.LocalDateTime.class));
    }

    @Test
    public void testCheckUnsupportedTypeForNonOptional() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Test String (should return null)
        JavaType stringType = typeFactory.constructType(String.class);
        String result = BeanUtil.checkUnsupportedType(stringType);
        assertNull("String should not be detected as unsupported type", result);

        // Test Integer (should return null)
        JavaType integerType = typeFactory.constructType(Integer.class);
        result = BeanUtil.checkUnsupportedType(integerType);
        assertNull("Integer should not be detected as unsupported type", result);

        // Test Boolean (should return null)
        JavaType booleanType = typeFactory.constructType(Boolean.class);
        result = BeanUtil.checkUnsupportedType(booleanType);
        assertNull("Boolean should not be detected as unsupported type", result);
    }

    @Test
    public void testCheckUnsupportedTypeErrorMessageFormat() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        JavaType optionalIntType = typeFactory.constructType(OptionalInt.class);
        String result = BeanUtil.checkUnsupportedType(optionalIntType);

        assertNotNull("Result should not be null for OptionalInt", result);
        assertTrue("Result should contain type description", result.contains("OptionalInt"));
        assertTrue("Result should follow expected error message format", 
                result.matches(".*Java 8 optional type .* not supported by default: add Module \".*\" to enable handling.*"));
    }
}

