package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Test for [databind#4071]: Allow deserialization of custom Throwable subclasses
 * that lack a single-String constructor by gracefully ignoring the "message" property.
 */
public class ThrowableDeserializer4071Test {

    /**
     * Custom Throwable with only default constructor (no single-String constructor).
     * This is the scenario that was failing before the fix.
     */
    public static class CustomThrowableNoStringCtor extends Throwable {
        private String customField;

        public CustomThrowableNoStringCtor() {
            super();
        }

        public String getCustomField() {
            return customField;
        }

        public void setCustomField(String customField) {
            this.customField = customField;
        }
    }

    /**
     * Custom Throwable with both default and single-String constructor.
     * This should continue to work as before.
     */
    public static class CustomThrowableWithStringCtor extends Throwable {
        private String customField;

        public CustomThrowableWithStringCtor() {
            super();
        }

        public CustomThrowableWithStringCtor(String message) {
            super(message);
        }

        public String getCustomField() {
            return customField;
        }

        public void setCustomField(String customField) {
            this.customField = customField;
        }
    }

    /**
     * Test that deserializing a custom Throwable without a single-String constructor
     * succeeds when JSON contains a "message" property (the fix for #4071).
     */
    @Test
    public void testDeserializeThrowableNoStringCtorWithMessage() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // JSON with message property - this would fail before the fix
        String json = "{\"message\":\"test message\",\"customField\":\"custom value\"}";

        // This should now work with the fix (previously would throw UnrecognizedPropertyException)
        CustomThrowableNoStringCtor result = mapper.readValue(json, CustomThrowableNoStringCtor.class);

        assertNotNull("Deserialization should succeed", result);
        assertEquals("custom value", result.getCustomField());
        // Message should be null since we don't have a String constructor to set it
        assertNull(result.getMessage());
    }

    /**
     * Test that deserializing a custom Throwable with a single-String constructor
     * still works correctly when JSON contains a "message" property.
     */
    @Test
    public void testDeserializeThrowableWithStringCtorWithMessage() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"message\":\"test message\",\"customField\":\"custom value\"}";

        CustomThrowableWithStringCtor result = mapper.readValue(json, CustomThrowableWithStringCtor.class);

        assertNotNull("Deserialization should succeed", result);
        assertEquals("test message", result.getMessage());
        assertEquals("custom value", result.getCustomField());
    }

    /**
     * Test that deserializing a custom Throwable without a single-String constructor
     * works when JSON does not contain a "message" property.
     */
    @Test
    public void testDeserializeThrowableNoStringCtorWithoutMessage() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"customField\":\"custom value\"}";

        CustomThrowableNoStringCtor result = mapper.readValue(json, CustomThrowableNoStringCtor.class);

        assertNotNull("Deserialization should succeed", result);
        assertEquals("custom value", result.getCustomField());
    }

    /**
     * Test case-insensitive handling of "message" property (e.g., "Message", "MESSAGE").
     */
    @Test
    public void testDeserializeThrowableNoStringCtorWithMessageCaseInsensitive() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // Test with different case variations of "message"
        String[] messageVariations = {"\"Message\":\"test\"", "\"MESSAGE\":\"test\"", "\"mEsSaGe\":\"test\""};

        for (String messageVar : messageVariations) {
            String json = "{" + messageVar + ",\"customField\":\"value\"}";

            CustomThrowableNoStringCtor result = mapper.readValue(json, CustomThrowableNoStringCtor.class);

            assertNotNull("Deserialization should succeed for: " + json, result);
            assertEquals("value", result.getCustomField());
        }
    }

    /**
     * Test that "suppressed" property is still handled correctly for Throwable without String constructor.
     */
    @Test
    public void testDeserializeThrowableNoStringCtorWithSuppressed() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"message\":\"test\",\"suppressed\":[{\"message\":\"suppressed1\"}]}";

        CustomThrowableNoStringCtor result = mapper.readValue(json, CustomThrowableNoStringCtor.class);

        assertNotNull("Deserialization should succeed", result);
        // The suppressed exception should be added
        assertEquals(1, result.getSuppressed().length);
    }
}

