package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonRootName;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Unit test for [databind#4047]: ObjectMapper.valueToTree should respect SerializationFeature.WRAP_ROOT_VALUE
 */
public class ObjectMapper4047Test {

    @JsonRootName("event")
    static class Event {
        private Long id;
        private String name;

        public Event() { }

        public Long getId() {
            return id;
        }

        public void setId(Long id) {
            this.id = id;
        }

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }
    }

    @Test
    public void testValueToTreeRespectsWrapRootValue() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper();
        // Enable WRAP_ROOT_VALUE feature as per trigger scenario
        objectMapper.enable(SerializationFeature.WRAP_ROOT_VALUE);

        Event event = new Event();
        event.setId(1L);
        event.setName("test");

        // Convert to tree
        JsonNode result = objectMapper.valueToTree(event);

        // Expected outcome: The resulting JsonNode should be wrapped in an outer object with the root name "event"
        assertNotNull("Result should not be null", result);
        assertTrue("Result should be an ObjectNode", result.isObject());

        ObjectNode rootNode = (ObjectNode) result;

        // The root node should contain the field "event" due to WRAP_ROOT_VALUE
        assertTrue("Root node should have 'event' field when WRAP_ROOT_VALUE is enabled", rootNode.has("event"));

        JsonNode innerNode = rootNode.get("event");
        assertNotNull("Inner node should not be null", innerNode);
        assertTrue("Inner node should be an object", innerNode.isObject());

        // Verify inner content matches the Event object
        assertEquals("id should be 1", 1L, innerNode.get("id").asLong());
        assertEquals("name should be 'test'", "test", innerNode.get("name").asText());
    }

    @Test
    public void testValueToTreeWithoutWrapRootValue() throws Exception {
        ObjectMapper objectMapper = new ObjectMapper();
        // Ensure WRAP_ROOT_VALUE is disabled (default)
        objectMapper.disable(SerializationFeature.WRAP_ROOT_VALUE);

        Event event = new Event();
        event.setId(1L);
        event.setName("test");

        // Convert to tree
        JsonNode result = objectMapper.valueToTree(event);

        // Verify the result is NOT wrapped
        assertNotNull("Result should not be null", result);
        assertTrue("Result should be an ObjectNode", result.isObject());

        ObjectNode rootNode = (ObjectNode) result;

        // The root node should NOT contain the field "event" when WRAP_ROOT_VALUE is disabled
        assertFalse("Root node should NOT have 'event' field when WRAP_ROOT_VALUE is disabled", rootNode.has("event"));
        assertTrue("Root node should have 'id' field", rootNode.has("id"));
        assertTrue("Root node should have 'name' field", rootNode.has("name"));

        assertEquals("id should be 1", 1L, rootNode.get("id").asLong());
        assertEquals("name should be 'test'", "test", rootNode.get("name").asText());
    }
}

