package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonIgnore;
import org.junit.Test;

import static org.junit.Assert.*;

public class IgnoreTransientWithJsonIgnore3948Test {

    static class BeanWithTransientIgnored {
        public String name;

        @JsonIgnore
        public transient String def;

        public BeanWithTransientIgnored() { }

        public BeanWithTransientIgnored(String name, String def) {
            this.name = name;
            this.def = def;
        }

        public String getDef() {
            return def;
        }
    }

    @Test
    public void testJsonIgnoreOnTransientField() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // By default, PROPAGATE_TRANSIENT_MARKER is disabled
        assertFalse(mapper.isEnabled(MapperFeature.PROPAGATE_TRANSIENT_MARKER));

        BeanWithTransientIgnored obj1 = new BeanWithTransientIgnored("test", "world");

        // Serialize
        String json = mapper.writeValueAsString(obj1);

        // The transient field with @JsonIgnore should not appear in JSON
        assertFalse("JSON should not contain the value 'world'", json.contains("world"));

        // Deserialize
        BeanWithTransientIgnored obj2 = mapper.readValue(json, BeanWithTransientIgnored.class);

        // The transient field should be null after deserialization
        assertNull("def should be null after deserialization", obj2.getDef());

        // Verify the fields are not equal (obj1 has value, obj2 is null)
        assertNotEquals("obj1.def and obj2.def should not be equal", obj1.getDef(), obj2.getDef());

        // The name field should be preserved
        assertEquals("test", obj2.name);
    }

    @Test
    public void testJsonIgnoreOnTransientFieldWithPropagateTransientEnabled() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.PROPAGATE_TRANSIENT_MARKER);

        BeanWithTransientIgnored obj1 = new BeanWithTransientIgnored("test", "world");

        // Serialize
