package com.fasterxml.jackson.databind.deser;

import java.util.Locale;

import org.junit.Test;

import com.fasterxml.jackson.databind.*;

import static org.junit.Assert.*;

/**
 * Test for issue #4009: Locale "" is deserialised as {@code null} if 
 * {@code ACCEPT_EMPTY_STRING_AS_NULL_OBJECT} is enabled.
 * 
 * This test verifies that empty string deserialization to Locale returns
 * {@code Locale.ROOT} instead of {@code null}, regardless of the 
 * {@code ACCEPT_EMPTY_STRING_AS_NULL_OBJECT} setting.
 */
public class LocaleDeser4009Test {

    @Test
    public void testEmptyStringToLocaleWithAcceptEmptyStringAsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT, true);

        // Empty string should deserialize to Locale.ROOT, not null
        // This tests issue #4009
        Locale result = mapper.readValue("\"\"", Locale.class);
        assertNotNull("Locale should not be null when deserializing empty string", result);
        assertEquals("Empty string should deserialize to Locale.ROOT", Locale.ROOT, result);
    }

    @Test
    public void testEmptyStringToLocaleWithoutAcceptEmptyStringAsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.configure(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT, false);

