import com.fasterxml.jackson.core.JsonFactory;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectMapperCopyWithTest {

    @Test
    public void testCopyWithNewFactory() throws Exception {
        // 1. Create original mapper with a specific factory
        JsonFactory originalFactory = new JsonFactory();
        ObjectMapper originalMapper = new ObjectMapper(originalFactory);

        // 2. Configure original mapper to ensure configuration is copied
        originalMapper.enable(SerializationFeature.INDENT_OUTPUT);

        // 3. Create a new factory to be used by the copy
        JsonFactory newFactory = new JsonFactory();

        // 4. Invoke the new copyWith method
        ObjectMapper copiedMapper = originalMapper.copyWith(newFactory);

        // 5. Verify the copied mapper is a distinct instance
        assertNotNull("Copied mapper should not be null", copiedMapper);
        assertNotSame("Copied mapper should be a new instance", originalMapper, copiedMapper);

        // 6. Verify the copied mapper uses the new factory
        assertSame("Copied mapper should use the provided new factory", newFactory, copiedMapper.getFactory());

        // 7. Verify the original mapper still uses the original factory
        assertSame("Original mapper should retain its original factory", originalFactory, originalMapper.getFactory());

        // 8. Verify configuration is preserved in the copy
        assertTrue("Copied mapper should inherit INDENT_OUTPUT feature", 
                copiedMapper.isEnabled(SerializationFeature.INDENT_OUTPUT));

        // 9. Verify the new factory has the copied mapper as its codec
        assertSame("New factory should have the copied mapper as codec", 
                copiedMapper, copiedMapper.getFactory().getCodec());

        // 10. Verify the original factory still has the original mapper as its codec
        assertSame("Original factory should retain original mapper as codec", 
                originalMapper, originalMapper.getFactory().getCodec());
    }

    @Test
    public void testCopyWithNullFactory() throws Exception {
        // 1. Create original mapper
        JsonFactory originalFactory = new JsonFactory();
        ObjectMapper originalMapper = new ObjectMapper(originalFactory);
        originalMapper.enable(SerializationFeature.INDENT_OUTPUT);

        // 2. Invoke copyWith with null (should behave like copy())
        ObjectMapper copiedMapper = originalMapper.copyWith(null);

        // 3. Verify distinct instance
        assertNotNull(copiedMapper);
        assertNotSame(originalMapper, copiedMapper);

        // 4. Verify factory is a copy of the original (not same instance, but same type)
        // According to patch: _jsonFactory = factory != null ? factory : src._jsonFactory.copy();
        assertNotSame("Factory should be a copy when null is passed", originalFactory, copiedMapper.getFactory());
        assertEquals("Factory class should be the same", originalFactory.getClass(), copiedMapper.getFactory().getClass());

        // 5. Verify configuration is preserved
        assertTrue(copiedMapper.isEnabled(SerializationFeature.INDENT_OUTPUT));
    }
}

