        CoercionAction action = configs.findCoercion(config, 
            LogicalType.Float, 
            Float.class, 
            CoercionInputShape.Integer);

        // Should not be Fail - integer to float is allowed even with ALLOW_COERCION_OF_SCALARS disabled
        assertNotEquals("Integer to Float coercion should be allowed even when ALLOW_COERCION_OF_SCALARS is disabled",
            CoercionAction.Fail, action);
