    public void testDoubleTypeIntegerCoercionAlsoAllowed() {
        // Create ObjectMapper and disable ALLOW_COERCION_OF_SCALARS
        ObjectMapper mapper = new ObjectMapper();
        DeserializationConfig config = mapper.getDeserializationConfig()
            .without(MapperFeature.ALLOW_COERCION_OF_SCALARS);

        // Create CoercionConfigs instance
        CoercionConfigs configs = new CoercionConfigs();

        // Test integer-to-double coercion should also NOT fail (Double is also Float logical type)
        CoercionAction action = configs.findCoercion(config, 
