            CoercionInputShape.Integer);

        // Should not be Fail - integer to Double is allowed even with ALLOW_COERCION_OF_SCALARS disabled
        assertNotEquals("Integer to Double coercion should be allowed even when ALLOW_COERCION_OF_SCALARS is disabled",
            CoercionAction.Fail, action);
