package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Test for Issue #3590 / CVE-2022-42003:
 * Verify that deep nesting of arrays is blocked when UNWRAP_SINGLE_VALUE_ARRAYS is enabled.
 * This prevents resource exhaustion vulnerabilities via deeply nested arrays.
 */
public class Issue3590Test {

    @Test
    public void testUnwrapSingleValueArrayValid() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        // Test byte primitive (covers _parseBytePrimitive)
        byte b = mapper.readValue("[10]", byte.class);
        assertEquals((byte) 10, b);

        // Test int primitive (covers _parseIntPrimitive)
        int i = mapper.readValue("[100]", int.class);
        assertEquals(100, i);

        // Test boolean primitive (covers _parseBooleanPrimitive)
        boolean bool = mapper.readValue("[true]", boolean.class);
        assertTrue(bool);

        // Test long primitive (covers _parseLongPrimitive)
        long l = mapper.readValue("[12345]", long.class);
        assertEquals(12345L, l);

        // Test short primitive (covers _parseShortPrimitive)
        short s = mapper.readValue("[1000]", short.class);
        assertEquals((short) 1000, s);

        // Test float primitive (covers _parseFloatPrimitive)
        float f = mapper.readValue("[1.5]", float.class);
        assertEquals(1.5f, f, 0.0f);

        // Test double primitive (covers _parseDoublePrimitive)
        double d = mapper.readValue("[2.5]", double.class);
        assertEquals(2.5, d, 0.0);
    }

    @Test
