package com.fasterxml.jackson.databind;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

import org.junit.Test;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.exc.InvalidDefinitionException;

import static org.junit.Assert.*;

/**
 * Test for issue #3559: Support null-valued Map fields with "any setter"
 * 
 * This test verifies that when a field annotated with @JsonAnySetter is a Map type
 * and is initially null, the system automatically creates and assigns an appropriate
 * Map instance during deserialization.
 */
public class AnySetterWithNullMapTest {

    static class BeanWithNullHashMap {
        public String name;

        @JsonAnySetter
        public Map<String, String> other = null;  // Explicitly null
    }

    static class BeanWithNullLinkedHashMap {
        public String name;

        @JsonAnySetter
        public Map<String, String> other = null;  // Explicitly null
    }

    static class BeanWithRawMap {
        public String name;

        @JsonAnySetter
        public Map<String, Object> other = null;  // Raw Map type
    }

    static class BeanWithInitializedMap {
        public String name;

        @JsonAnySetter
        public Map<String, String> other = new HashMap<>();  // Already initialized
    }

    /**
     * Test that a null HashMap field with @JsonAnySetter gets initialized and populated
     */
    @Test
    public void testNullHashMapAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"name\":\"test\",\"extra1\":\"value1\",\"extra2\":\"value2\"}";

        BeanWithNullHashMap bean = mapper.readValue(json, BeanWithNullHashMap.class);

        assertNotNull("Map should be initialized", bean.other);
        assertEquals("value1", bean.other.get("extra1"));
        assertEquals("value2", bean.other.get("extra2"));
        assertEquals("test", bean.name);
    }

    /**
     * Test that a null LinkedHashMap field with @JsonAnySetter gets initialized and populated
     */
    @Test
    public void testNullLinkedHashMapAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"name\":\"test\",\"extra1\":\"value1\"}";

        BeanWithNullLinkedHashMap bean = mapper.readValue(json, BeanWithNullLinkedHashMap.class);

        assertNotNull("Map should be initialized", bean.other);
        assertEquals("value1", bean.other.get("extra1"));
        assertEquals("test", bean.name);
    }

    /**
     * Test that a raw Map field (Map.class) defaults to LinkedHashMap and gets initialized
     */
    @Test
    public void testRawMapAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"name\":\"test\",\"extra\":\"value\"}";

        BeanWithRawMap bean = mapper.readValue(json, BeanWithRawMap.class);

        assertNotNull("Map should be initialized", bean.other);
        assertEquals("value", bean.other.get("extra"));
        assertTrue("Should be LinkedHashMap for raw Map type", bean.other instanceof LinkedHashMap);
        assertEquals("test", bean.name);
    }

    /**
     * Test that an already initialized Map field still works correctly
     */
    @Test
    public void testInitializedMapAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"name\":\"test\",\"extra\":\"value\"}";

        BeanWithInitializedMap bean = mapper.readValue(json, BeanWithInitializedMap.class);

        assertNotNull("Map should exist", bean.other);
        assertEquals("value", bean.other.get("extra"));
        assertEquals("test", bean.name);
    }

    /**
     * Test that multiple extra properties are all captured in the any-setter map
     */
    @Test
    public void testMultipleAnySetterProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        String json = "{\"name\":\"test\",\"prop1\":\"val1\",\"prop2\":\"val2\",\"prop3\":\"val3\"}";

        BeanWithNullHashMap bean = mapper.readValue(json, BeanWithNullHashMap.class);

        assertNotNull("Map should be initialized", bean.other);
        assertEquals(3, bean.other.size());
        assertEquals("val1", bean.other.get("prop1"));
        assertEquals("val2", bean.other.get("prop2"));
        assertEquals("val3", bean.other.get("prop3"));
    }

    /**
     * Test that JsonMappingException factory methods handle null context safely
     * This tests the _generator helper method added in the patch
     */
    @Test
    public void testJsonMappingExceptionWithNullSerializerProvider() {
        // This should not throw NullPointerException
        JsonMappingException ex = JsonMappingException.from((SerializerProvider) null, "Test message");
        assertNotNull("Exception should be created", ex);
        assertEquals("Test message", ex.getMessage());
    }

    /**
     * Test that JsonMappingException factory methods handle null context safely with Throwable
     * This tests the focal method from the patch
     */
    @Test
    public void testJsonMappingExceptionWithNullSerializerProviderAndThrowable() {
        Throwable cause = new IllegalArgumentException("Cause");
        // This should not throw NullPointerException
        JsonMappingException ex = JsonMappingException.from((SerializerProvider) null, "Test message", cause);
        assertNotNull("Exception should be created", ex);
        assertEquals("Test message", ex.getMessage());
        assertEquals(cause, ex.getCause());
    }

    /**
     * Test that JsonMappingException factory methods handle null DeserializationContext safely
     * This tests the _parser helper method added in the patch
     */
    @Test
    public void testJsonMappingExceptionWithNullDeserializationContext() {
        // This should not throw NullPointerException
        JsonMappingException ex = JsonMappingException.from((DeserializationContext) null, "Test message");
        assertNotNull("Exception should be created", ex);
        assertEquals("Test message", ex.getMessage());
    }

    /**
     * Test that JsonMappingException factory methods handle null DeserializationContext safely with Throwable
     */
    @Test
    public void testJsonMappingExceptionWithNullDeserializationContextAndThrowable() {
        Throwable cause = new RuntimeException("Cause");
        // This should not throw NullPointerException
        JsonMappingException ex = JsonMappingException.from((DeserializationContext) null, "Test message", cause);
        assertNotNull("Exception should be created", ex);
        assertEquals("Test message", ex.getMessage());
        assertEquals(cause, ex.getCause());
    }
}

