package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.cfg.CoercionAction;
import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import com.fasterxml.jackson.databind.type.LogicalType;
import org.junit.Test;

import java.math.BigDecimal;

import static org.junit.Assert.*;

public class IntToFloatCoercionTest {

    static class FloatBean {
        public float value;
    }

    static class FloatWrapperBean {
        public Float value;
    }

    static class DoubleBean {
        public double value;
    }

    static class DoubleWrapperBean {
        public Double value;
    }

    static class BigDecimalBean {
        public BigDecimal value;
    }

    @Test
    public void testFloatPrimitiveWithCoercionFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        try {
            mapper.readValue("{\"value\": 11}", FloatBean.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("Integer value"));
        }
    }

    @Test
    public void testFloatWrapperWithCoercionFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        try {
            mapper.readValue("{\"value\": 11}", FloatWrapperBean.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("Integer value"));
        }
    }

    @Test
    public void testDoublePrimitiveWithCoercionFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        try {
            mapper.readValue("{\"value\": 11}", DoubleBean.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("Integer value"));
        }
    }

    @Test
    public void testDoubleWrapperWithCoercionFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        try {
            mapper.readValue("{\"value\": 11}", DoubleWrapperBean.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("Integer value"));
        }
    }

    @Test
    public void testBigDecimalWithCoercionFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        try {
            mapper.readValue("{\"value\": 11}", BigDecimalBean.class);
            fail("Expected MismatchedInputException");
        } catch (MismatchedInputException e) {
            assertTrue(e.getMessage().contains("Integer value"));
        }
    }

    @Test
    public void testFloatPrimitiveWithCoercionAsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        FloatBean bean = mapper.readValue("{\"value\": 11}", FloatBean.class);
        assertEquals(0.0f, bean.value, 0.0f);
    }

    @Test
    public void testFloatWrapperWithCoercionAsNull() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.AsNull);

        FloatWrapperBean bean = mapper.readValue("{\"value\": 11}", FloatWrapperBean.class);
        assertNull(bean.value);
    }

    @Test
    public void testFloatPrimitiveWithCoercionAsEmpty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        FloatBean bean = mapper.readValue("{\"value\": 11}", FloatBean.class);
        assertEquals(0.0f, bean.value, 0.0f);
    }

    @Test
    public void testFloatWrapperWithCoercionAsEmpty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.AsEmpty);

        FloatWrapperBean bean = mapper.readValue("{\"value\": 11}", FloatWrapperBean.class);
        assertEquals(0.0f, bean.value, 0.0f);
    }

    @Test
    public void testDefaultCoercionStillWorks() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Default behavior should allow integer to float coercion

        FloatBean floatBean = mapper.readValue("{\"value\": 11}", FloatBean.class);
        assertEquals(11.0f, floatBean.value, 0.0f);

        FloatWrapperBean floatWrapperBean = mapper.readValue("{\"value\": 11}", FloatWrapperBean.class);
        assertEquals(11.0f, floatWrapperBean.value, 0.0f);

        DoubleBean doubleBean = mapper.readValue("{\"value\": 11}", DoubleBean.class);
        assertEquals(11.0d, doubleBean.value, 0.0d);

        DoubleWrapperBean doubleWrapperBean = mapper.readValue("{\"value\": 11}", DoubleWrapperBean.class);
        assertEquals(11.0d, doubleWrapperBean.value, 0.0d);

        BigDecimalBean bigDecimalBean = mapper.readValue("{\"value\": 11}", BigDecimalBean.class);
        assertEquals(new BigDecimal("11"), bigDecimalBean.value);
    }

    @Test
    public void testFloatCoercionWithFloatInput() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.coercionConfigFor(LogicalType.Float)
              .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail);

        // Float input should still work even with Integer coercion set to Fail
        FloatBean bean = mapper.readValue("{\"value\": 11.5}", FloatBean.class);
