package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.JsonMerge;
import com.fasterxml.jackson.annotation.JsonSubTypes;
import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;

/**
 * Test for verifying the fix of issue #2541:
 * Support merging polymorphic properties in SettableBeanProperty.deserializeWith
 */
public class SettableBeanPropertyPolymorphicMergeTest {

    @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, property = "type")
    @JsonSubTypes({
        @JsonSubTypes.Type(value = ConcreteThingy.class, name = "concrete")
    })
    public static abstract class BaseThingy {
        public String type;
    }

    public static class ConcreteThingy extends BaseThingy {
        public String name;
        public int value;

        public ConcreteThingy() {}

        public ConcreteThingy(String name, int value) {
            this.name = name;
            this.value = value;
        }
    }

    public static class Request {
        @JsonMerge
        public BaseThingy thingy;

        public Request() {}

        public Request(BaseThingy thingy) {
            this.thingy = thingy;
        }
    }

    @Test
    public void testPolymorphicPropertyMerge() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // As per patch instructions, disable fail on unknown properties to allow merging
        // polymorphic properties without unknown property exceptions for type ids
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

        // Create existing object with initial values
        ConcreteThingy existingThingy = new ConcreteThingy("originalName", 100);
        Request request = new Request(existingThingy);

        // JSON to merge: updates 'value', keeps 'name' from existing object
        // Includes 'type' property which is handled by polymorphic setup
        String json = "{\"thingy\": {\"type\": \"concrete\", \"value\": 200}}";

        // Perform update (merge) using readerForUpdating
        Request result = mapper.readerForUpdating(request).readValue(json);

        // Verify the request object is the same instance (updated in place)
        assertSame(request, result);
        assertNotNull(result.thingy);

        // Verify the type is preserved
        assertEquals("ConcreteThingy", result.thingy.getClass().getSimpleName());

        ConcreteThingy mergedThingy = (ConcreteThingy) result.thingy;
        // 'name' should be preserved from existing object (merge behavior)
        assertEquals("originalName", mergedThingy.name);
        // 'value' should be updated from JSON
        assertEquals(200, mergedThingy.value);
    }
}

