package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.databind.BeanDescription;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

/**
 * Test for [databind#2543]: Introspection includes delegating ctor's
 * only parameter as a property in BeanDescription.
 * 
 * Verifies that when a class has a @JsonCreator(mode = Mode.DELEGATING) factory method,
 * the parameter of that method is not incorrectly added as a property in BeanDescription.
 */
public class DelegatingCreatorIntrospectionTest {

    static class Wrapper {
        @JsonProperty("value")
        public String value;

        public Wrapper() { }
        public Wrapper(String v) { value = v; }
    }

    static class Target {
        protected String value;

        protected Target(String v) {
            this.value = v;
        }

        public String getValue() { return value; }

        @JsonCreator(mode = JsonCreator.Mode.DELEGATING)
        public static Target fromWrapper(Wrapper wrapper) {
            return new Target(wrapper.value);
        }
    }

    @Test
    public void testDelegatingCreatorParameterNotIncludedInProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        JavaType type = TypeFactory.defaultInstance().constructType(Target.class);
        BeanDescription beanDesc = mapper.getSerializationConfig().introspect(type);

        List<BeanPropertyDefinition> properties = beanDesc.findProperties();

        // The Target class has one property 'value' (from field/getter).
        // The delegating creator parameter 'wrapper' should NOT be included as a property.
        // Before the fix, the 'wrapper' parameter would be included, resulting in 2 properties.
        assertEquals("Should have exactly one property", 1, properties.size());

        boolean hasValue = false;
        for (BeanPropertyDefinition prop : properties) {
            if ("value".equals(prop.getName())) {
                hasValue = true;
            }
        }
        assertTrue("Should have property 'value'", hasValue);
    }
}

