package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.module.SimpleModule;
import com.fasterxml.jackson.databind.type.ArrayType;
import org.junit.Test;

import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.*;

/**
 * Test for issue #4216: Primitive array deserializer cannot being captured by {@code DeserializerModifier}
 * 
 * This test verifies that {@link BeanDeserializerModifier#modifyArrayDeserializer} is called
 * for both primitive arrays (e.g., byte[]) and object arrays (e.g., Byte[]).
 */
public class PrimitiveArrayDeserializerModifier4216Test {

    static class TestBean {
        public byte[] primitiveArray;
        public Byte[] objectArray;

        public TestBean() {}
    }

    static class TrackingModifier extends BeanDeserializerModifier {
        private final AtomicInteger arrayDeserializerCount = new AtomicInteger(0);

        @Override
        public JsonDeserializer<?> modifyArrayDeserializer(DeserializationConfig config,
                ArrayType arrayType, BeanDescription beanDesc, JsonDeserializer<?> deserializer) {
            arrayDeserializerCount.incrementAndGet();
            return deserializer;
        }

        public int getArrayDeserializerCount() {
            return arrayDeserializerCount.get();
        }
    }

    @Test
    public void testPrimitiveArrayDeserializerModifier() throws Exception {
        TrackingModifier modifier = new TrackingModifier();

        SimpleModule module = new SimpleModule();
        module.setDeserializerModifier(modifier);

        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(module);

        String json = "{\"primitiveArray\":[1,2,3],\"objectArray\":[4,5,6]}";
        TestBean bean = mapper.readValue(json, TestBean.class);

        assertNotNull(bean.primitiveArray);
        assertEquals(3, bean.primitiveArray.length);
        assertNotNull(bean.objectArray);
        assertEquals(3, bean.objectArray.length);

        // Both primitive and object arrays should trigger the modifier
        // Before fix: count would be 1 (only object array)
        // After fix: count should be 2 (both primitive and object arrays)
        assertEquals(2, modifier.getArrayDeserializerCount());
    }

    @Test
    public void testIntArrayDeserializerModifier() throws Exception {
        TrackingModifier modifier = new TrackingModifier();

        SimpleModule module = new SimpleModule();
        module.setDeserializerModifier(modifier);

        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(module);

        String json = "{\"primitiveArray\":[1,2,3],\"objectArray\":[4,5,6]}";
        TestBean bean = mapper.readValue(json, TestBean.class);

        // Verify deserialization works correctly
        assertArrayEquals(new byte[]{1, 2, 3}, bean.primitiveArray);
        assertArrayEquals(new Byte[]{4, 5, 6}, bean.objectArray);

        // Both array types should have triggered the modifier
        assertEquals(2, modifier.getArrayDeserializerCount());
    }
}

