/**
 * Unit tests for {@link JsonNode#withObjectProperty(String)} and
 * {@link JsonNode#withArrayProperty(String)} methods.
 */
public class JsonNodeWithPropertyTest {

    private final ObjectMapper MAPPER = new ObjectMapper();

    @Test
    public void testWithObjectProperty_CreatesNewNode() throws Exception {
        ObjectNode root = MAPPER.createObjectNode();

        ObjectNode child = root.withObjectProperty("newProperty");

        assertNotNull(child);
        assertTrue(child.isObject());
        assertTrue(root.has("newProperty"));
        assertSame(child, root.get("newProperty"));
    }

    @Test
    public void testWithObjectProperty_ReturnsExistingNode() throws Exception {
        ObjectNode root = MAPPER.createObjectNode();
        ObjectNode existingChild = MAPPER.createObjectNode();
        root.set("existingProperty", existingChild);

        ObjectNode returnedChild = root.withObjectProperty("existingProperty");

        assertSame(existingChild, returnedChild);
    }

    @Test
    public void testWithObjectProperty_ReplacesNullNode() throws Exception {
        ObjectNode root = MAPPER.createObjectNode();
        root.putNull("nullProperty");

        ObjectNode child = root.withObjectProperty("nullProperty");

        assertNotNull(child);
        assertTrue(child.isObject());
        assertFalse(child.isNull());
    }

