    public void testWithObjectProperty_ThrowsOnWrongType() throws Exception {
        ObjectNode root = MAPPER.createObjectNode();
        root.put("textProperty", "some text");

        UnsupportedOperationException exception = assertThrows(
            UnsupportedOperationException.class,
            () -> root.withObjectProperty("textProperty")
