        assertNotNull(type);
        assertEquals(String.class, type.getRawClass());

        // Test parameterized type
        JavaType mapType = parser.parse("java.util.Map<java.lang.String, java.lang.Integer>");
        assertNotNull(mapType);
        assertEquals(Map.class, mapType.getRawClass());
    }

    @Test
    public void testTypeLengthLimit() throws Exception {
        TypeParser parser = new TypeParser(_factory);

        // Create a type string that exceeds MAX_TYPE_LENGTH (64,000)
        StringBuilder sb = new StringBuilder();
        sb.append("java.lang.String");
        while (sb.length() <= TypeParser.MAX_TYPE_LENGTH) {
            sb.append(", java.lang.String");
        }

        String longType = sb.toString();

        try {
            parser.parse(longType);
            fail("Expected IllegalArgumentException for type string exceeding length limit");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("too long"));
            assertTrue(e.getMessage().contains("maximum length allowed: 64000"));
        }
    }

    @Test
    public void testTypeNestingLimit() throws Exception {
        TypeParser parser = new TypeParser(_factory);

        // Create a deeply nested type that exceeds MAX_TYPE_NESTING (1000)
        // We need 1001 levels of nesting to trigger the error
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < TypeParser.MAX_TYPE_NESTING + 1; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < TypeParser.MAX_TYPE_NESTING + 1; i++) {
            sb.append(">");
        }

        String nestedType = sb.toString();

        try {
            parser.parse(nestedType);
            fail("Expected IllegalArgumentException for type exceeding nesting limit");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("too deeply nested"));
            assertTrue(e.getMessage().contains("exceeds maximum of 1000 nesting levels"));
        }
    }

    @Test
    public void testErrorMessageTruncation() throws Exception {
        TypeParser parser = new TypeParser(_factory);

        // Create a very long type string to test truncation in error messages
        // The _quoteTruncated method truncates strings longer than 1000 characters
        StringBuilder sb = new StringBuilder();
        sb.append("java.lang.String");
        while (sb.length() <= TypeParser.MAX_TYPE_LENGTH) {
            sb.append(", java.lang.String");
        }

        String longType = sb.toString();

        try {
            parser.parse(longType);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // Message should contain truncated version since input > 1000 chars
            assertTrue(e.getMessage().contains("[truncated"));
        }
    }

    @Test
    public void testTypeNestingAtLimit() throws Exception {
        TypeParser parser = new TypeParser(_factory);

        // Create a deeply nested type that is exactly at MAX_TYPE_NESTING (1000)
        // This should succeed without throwing an exception
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < TypeParser.MAX_TYPE_NESTING; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < TypeParser.MAX_TYPE_NESTING; i++) {
            sb.append(">");
        }

        String nestedType = sb.toString();

        // This should not throw an exception (at the limit, not exceeding)
        JavaType type = parser.parse(nestedType);
        assertNotNull(type);
    }
}

