package com.fasterxml.jackson.databind.deser.std;

import java.io.IOException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.module.SimpleModule;
import org.junit.Test;

import static org.junit.Assert.*;

public class StdNodeBasedDeserializerTest {

    static class MyObject {
        public String name;
        public int value;

        public MyObject() {}

        public MyObject(String name, int value) {
            this.name = name;
            this.value = value;
        }

        public void updateFromNode(JsonNode node) {
            if (node.has("name")) {
                this.name = node.get("name").asText();
            }
            if (node.has("value")) {
                this.value = node.get("value").asInt();
            }
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            MyObject myObject = (MyObject) obj;
            return value == myObject.value &&
                   (name != null ? name.equals(myObject.name) : myObject.name == null);
        }
    }

    static class MyDeserializer extends StdNodeBasedDeserializer<MyObject> {
        public MyDeserializer() {
            super(MyObject.class);
        }

        @Override
        public MyObject convert(JsonNode root, DeserializationContext ctxt) throws IOException {
            MyObject obj = new MyObject();
            if (root.has("name")) {
                obj.name = root.get("name").asText();
            }
            if (root.has("value")) {
                obj.value = root.get("value").asInt();
            }
            return obj;
        }

        @Override
        public MyObject convert(JsonNode root, DeserializationContext ctxt, MyObject existing) throws IOException {
            existing.updateFromNode(root);
            return existing;
        }
    }

    static class NoUpdateDeserializer extends StdNodeBasedDeserializer<MyObject> {
        public NoUpdateDeserializer() {
            super(MyObject.class);
        }

        @Override
        public MyObject convert(JsonNode root, DeserializationContext ctxt) throws IOException {
            MyObject obj = new MyObject();
            if (root.has("name")) {
                obj.name = root.get("name").asText();
            }
            if (root.has("value")) {
                obj.value = root.get("value").asInt();
            }
            return obj;
        }
    }

    @Test
    public void testReaderForUpdatingWithCustomConvert() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        MyDeserializer deserializer = new MyDeserializer();
        mapper.registerModule(new SimpleModule().addDeserializer(MyObject.class, deserializer));

        MyObject existing = new MyObject("original", 100);
        String json = "{\"name\":\"updated\",\"value\":200}";

        MyObject result = mapper.readerForUpdating(existing).readValue(json, MyObject.class);

        assertEquals("updated", result.name);
        assertEquals(200, result.value);
        assertSame(existing, result);
    }

    @Test
    public void testNormalDeserialization() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        MyDeserializer deserializer = new MyDeserializer();
        mapper.registerModule(new SimpleModule().addDeserializer(MyObject.class, deserializer));

        String json = "{\"name\":\"test\",\"value\":42}";
        MyObject result = mapper.readValue(json, MyObject.class);

        assertEquals("test", result.name);
        assertEquals(42, result.value);
    }

    @Test
    public void testReaderForUpdatingWithoutOverride() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        NoUpdateDeserializer deserializer = new NoUpdateDeserializer();
        mapper.registerModule(new SimpleModule().addDeserializer(MyObject.class, deserializer));

        MyObject existing = new MyObject("original", 100);
        String json = "{\"name\":\"updated\",\"value\":200}";

        MyObject result = mapper.readerForUpdating(existing).readValue(json, MyObject.class);

        assertNotNull(result);
        assertEquals("updated", result.name);
        assertEquals(200, result.value);
        assertNotSame(existing, result);
    }
}

