package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Test class for CVE-2022-42003 fix - preventing deep wrapper array nesting
 * with UNWRAP_SINGLE_VALUE_ARRAYS feature.
 */
public class StdDeserializerNestedArrayTest {

    @Test
    public void testNestedArrayRejectedForBoolean() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        // Nested array should be rejected
        try {
            mapper.readValue("[[[true]]]", Boolean.TYPE);
            fail("Expected MismatchedInputException to be thrown");
        } catch (MismatchedInputException e) {
            // Expected
        }

        // Single-level array should still work
        Boolean result = mapper.readValue("[true]", Boolean.TYPE);
        assertTrue(result);
    }

    @Test
    public void testNestedArrayRejectedForShort() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        // Nested array should be rejected
        try {
            mapper.readValue("[[[123]]]", Short.TYPE);
            fail("Expected MismatchedInputException to be thrown");
        } catch (MismatchedInputException e) {
            // Expected
        }

        // Single-level array should still work
        Short result = mapper.readValue("[123]", Short.TYPE);
        assertEquals((short) 123, (short) result);
    }

