package com.fasterxml.jackson.databind;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

import org.junit.Test;

import com.fasterxml.jackson.annotation.JsonAnySetter;

import static org.junit.Assert.*;

/**
 * Test class for verifying null-valued Map fields with @JsonAnySetter support.
 * Related to issue #3559.
 */
public class JsonAnySetterNullMapTest {

    /**
     * Test class with null-valued Map field annotated with @JsonAnySetter
     */
    static class BeanWithNullAnySetter {
        public String name;

        @JsonAnySetter
        public Map<String, Object> extraProperties;  // Initially null

        public BeanWithNullAnySetter() { }
    }

    /**
     * Test class with initialized Map field annotated with @JsonAnySetter
     */
    static class BeanWithInitializedAnySetter {
        public String name;

        @JsonAnySetter
        public Map<String, Object> extraProperties = new HashMap<>();

        public BeanWithInitializedAnySetter() { }
    }

    /**
     * Test class with LinkedHashMap field annotated with @JsonAnySetter
     */
    static class BeanWithLinkedHashMapAnySetter {
        public String name;

        @JsonAnySetter
        public LinkedHashMap<String, Object> extraProperties;  // Initially null

        public BeanWithLinkedHashMapAnySetter() { }
    }

    /**
     * Test that null-valued Map field with @JsonAnySetter gets auto-initialized
     * and populated during deserialization.
     */
    @Test
    public void testNullMapFieldWithAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"key1\":\"value1\",\"key2\":\"value2\"}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Bean should not be null", bean);
        assertEquals("Name should be deserialized correctly", "test", bean.name);
        assertNotNull("extraProperties Map should be auto-initialized", bean.extraProperties);
        assertEquals("Map should contain 2 extra properties", 2, bean.extraProperties.size());
        assertEquals("key1 should have correct value", "value1", bean.extraProperties.get("key1"));
        assertEquals("key2 should have correct value", "value2", bean.extraProperties.get("key2"));
    }

    /**
     * Test that initialized Map field with @JsonAnySetter still works correctly.
     */
    @Test
    public void testInitializedMapFieldWithAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"key1\":\"value1\"}";

        BeanWithInitializedAnySetter bean = mapper.readValue(json, BeanWithInitializedAnySetter.class);

        assertNotNull("Bean should not be null", bean);
        assertEquals("Name should be deserialized correctly", "test", bean.name);
        assertNotNull("extraProperties Map should not be null", bean.extraProperties);
        assertEquals("Map should contain 1 extra property", 1, bean.extraProperties.size());
        assertEquals("key1 should have correct value", "value1", bean.extraProperties.get("key1"));
    }

    /**
     * Test that null-valued LinkedHashMap field with @JsonAnySetter gets auto-initialized.
     */
    @Test
    public void testNullLinkedHashMapFieldWithAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"key1\":\"value1\"}";

        BeanWithLinkedHashMapAnySetter bean = mapper.readValue(json, BeanWithLinkedHashMapAnySetter.class);

        assertNotNull("Bean should not be null", bean);
        assertEquals("Name should be deserialized correctly", "test", bean.name);
        assertNotNull("extraProperties LinkedHashMap should be auto-initialized", bean.extraProperties);
        assertTrue("Should be LinkedHashMap instance", bean.extraProperties instanceof LinkedHashMap);
        assertEquals("Map should contain 1 extra property", 1, bean.extraProperties.size());
        assertEquals("key1 should have correct value", "value1", bean.extraProperties.get("key1"));
    }

    /**
     * Test that raw Map type defaults to LinkedHashMap when null.
     */
    @Test
    public void testRawMapTypeDefaultsToLinkedHashMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"prop\":\"value\"}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Map should be auto-initialized", bean.extraProperties);
        // The implementation defaults to LinkedHashMap for raw Map.class
        assertTrue("Raw Map type should default to LinkedHashMap", 
            bean.extraProperties instanceof LinkedHashMap);
    }

    /**
     * Test that JsonMappingException.from handles null DeserializationContext safely.
     */
    @Test
    public void testJsonMappingExceptionFromWithNullContext() {
        // This tests the _parser helper method in JsonMappingException
        // that handles null DeserializationContext
        try {
            JsonMappingException ex = JsonMappingException.from((DeserializationContext) null, "Test message");
            assertNotNull("Exception should be created even with null context", ex);
            assertEquals("Message should be preserved", "Test message", ex.getMessage());
        } catch (Exception e) {
            fail("Should not throw exception with null context: " + e.getMessage());
        }
    }

    /**
     * Test that JsonMappingException.from handles null DeserializationContext with Throwable.
     */
    @Test
    public void testJsonMappingExceptionFromWithNullContextAndThrowable() {
        Throwable cause = new IllegalArgumentException("Cause");
        try {
            JsonMappingException ex = JsonMappingException.from((DeserializationContext) null, "Test message", cause);
            assertNotNull("Exception should be created even with null context", ex);
            assertEquals("Message should be preserved", "Test message", ex.getMessage());
            assertEquals("Cause should be preserved", cause, ex.getCause());
        } catch (Exception e) {
            fail("Should not throw exception with null context: " + e.getMessage());
        }
    }

    /**
     * Test that multiple extra properties are correctly added to auto-initialized Map.
     */
    @Test
    public void testMultipleExtraPropertiesWithNullMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"a\":1,\"b\":2,\"c\":3,\"d\":4}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Map should be auto-initialized", bean.extraProperties);
        assertEquals("Map should contain 4 extra properties", 4, bean.extraProperties.size());
        assertEquals(1, bean.extraProperties.get("a"));
        assertEquals(2, bean.extraProperties.get("b"));
        assertEquals(3, bean.extraProperties.get("c"));
        assertEquals(4, bean.extraProperties.get("d"));
    }

    /**
     * Test that nested objects in extra properties work with auto-initialized Map.
     */
    @Test
    public void testNestedObjectsWithNullMap() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"nested\":{\"inner\":\"value\"}}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Map should be auto-initialized", bean.extraProperties);
        assertEquals("Map should contain 1 extra property", 1, bean.extraProperties.size());
        assertTrue("Nested object should be deserialized as Map", 
            bean.extraProperties.get("nested") instanceof Map);
        @SuppressWarnings("unchecked")
        Map<String, Object> nested = (Map<String, Object>) bean.extraProperties.get("nested");
        assertEquals("Nested property should be correct", "value", nested.get("inner"));
    }
}

