package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.annotation.JsonSetter;
import com.fasterxml.jackson.annotation.Nulls;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class FieldPropertyNullSkipTest {

    static class Inner {
        public String field1;

        public Inner() {}

        public Inner(String field1) {
            this.field1 = field1;
        }
    }

    static class Middle {
        @JsonSetter(nulls = Nulls.SKIP)
        private List<Inner> list1 = new ArrayList<>();

        // Added field1 to match JSON structure in tests and prevent UnrecognizedProperty error
        public String field1;

        public Middle() {}

        public List<Inner> getList1() {
            return list1;
        }

        public void setList1(List<Inner> list1) {
            this.list1 = list1;
        }
    }

    static class Outer {
        public List<Middle> list1;

        public Outer() {}
    }

    static class BeanWithField {
        @JsonSetter(nulls = Nulls.SKIP)
        public String value = "default";

        public BeanWithField() {}
    }

    static class BeanWithSetter {
        private String value = "default";

        public BeanWithSetter() {}

        @JsonSetter(nulls = Nulls.SKIP)
        public void setValue(String value) {
            this.value = value;
        }

        public String getValue() {
            return value;
        }
    }

    // Class without Nulls.SKIP to verify default behavior
    static class BeanWithoutSkip {
        public String value = "default";

        public BeanWithoutSkip() {}
    }

    @Test
    public void testNullSkipWithFieldProperty() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        // JSON structure fixed to match Middle class (added field1 to Middle class)
        // Removed assertion that accessed index 0 of potentially empty list
        String json = "{ \"list1\": [ { \"list1\": null, \"field1\": \"data\" } ] }";

        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull(outer.list1);
        assertEquals(1, outer.list1.size());

        Middle middle = outer.list1.get(0);
        assertNotNull("list1 should not be null when Nulls.SKIP is configured", middle.getList1());
        assertEquals(0, middle.getList1().size());
        // Verify the other field was set correctly
        assertEquals("data", middle.field1);
    }

    @Test
    public void testNullSkipWithSimpleField() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{ \"value\": null }";

        BeanWithField bean = mapper.readValue(json, BeanWithField.class);

        assertNotNull("value should not be null when Nulls.SKIP is configured", bean.value);
        assertEquals("default", bean.value);
    }

    @Test
    public void testNullSkipWithSetterMethod() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{ \"value\": null }";

        BeanWithSetter bean = mapper.readValue(json, BeanWithSetter.class);

        assertNotNull("value should not be null when Nulls.SKIP is configured", bean.getValue());
        assertEquals("default", bean.getValue());
    }

    @Test
    public void testNullSkipWithNonNullValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{ \"value\": \"custom\" }";

        BeanWithField bean = mapper.readValue(json, BeanWithField.class);

        assertNotNull(bean.value);
        assertEquals("custom", bean.value);
    }

    @Test
    public void testNullSkipWithNestedObjects() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{ \"list1\": [" +
            "{ \"list1\": null, \"field1\": \"data1\" }," +
            "{ \"list1\": [{ \"field1\": \"data2\" }], \"field1\": \"data3\" }," +
            "{ \"list1\": null, \"field1\": \"data4\" }" +
            "] }";

        Outer outer = mapper.readValue(json, Outer.class);

        assertNotNull(outer.list1);
        assertEquals(3, outer.list1.size());

        // First middle: list1 was null in JSON, should keep initialized empty list
        Middle middle1 = outer.list1.get(0);
        assertNotNull("First middle list1 should not be null", middle1.getList1());
        assertEquals(0, middle1.getList1().size());
        assertEquals("data1", middle1.field1);

        // Second middle: list1 had value in JSON, should be set
        Middle middle2 = outer.list1.get(1);
        assertNotNull("Second middle list1 should not be null", middle2.getList1());
        assertEquals(1, middle2.getList1().size());
        assertEquals("data2", middle2.getList1().get(0).field1);
        assertEquals("data3", middle2.field1);

        // Third middle: list1 was null in JSON, should keep initialized empty list
        Middle middle3 = outer.list1.get(2);
        assertNotNull("Third middle list1 should not be null", middle3.getList1());
        assertEquals(0, middle3.getList1().size());
        assertEquals("data4", middle3.field1);
    }

    @Test
    public void testNullAssignmentWithoutSkip() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{ \"value\": null }";

        BeanWithoutSkip bean = mapper.readValue(json, BeanWithoutSkip.class);

        // Without Nulls.SKIP, null should be assigned
        assertNull("value should be null when Nulls.SKIP is not configured", bean.value);
    }
}

