package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.*;
import com.fasterxml.jackson.databind.*;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

/**
 * Test for issue #4309: {@code @JsonSetter(nulls=...)} handling of {@code Collection} {@code null} values
 * during deserialization with {@code READ_UNKNOWN_ENUM_VALUES_AS_NULL} and {@code FAIL_ON_INVALID_SUBTYPE}.
 *
 * Verifies that null values resulting from unknown enums or invalid subtypes are skipped
 * when {@code Nulls.SKIP} is configured for collection contents.
 * 
 * Optimized to cover:
 * 1. handleNonArray path (Single Value as Array) with unknown enum -> null -> skip.
 * 2. _deserializeWithObjectId path with invalid subtype -> null -> skip.
 * 3. _deserializeWithObjectId path with explicit null token -> skip.
 * 4. _deserializeWithObjectId delegating to handleNonArray (Single Value with ObjectId).
 */
public class CollectionDeserializer4309Test {

    // --- Test for handleNonArray path (Single Value as Array) ---

    public enum StatusEnum {
        OK, FAIL
    }

    public static class BeanWithEnumList {
        @JsonSetter(contentNulls = Nulls.SKIP)
        public List<StatusEnum> statuses;
    }

    @Test
    public void testSkipNullsFromUnknownEnumSingleValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Enable reading unknown enums as null
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);
        // Enable accepting single value as array to trigger handleNonArray
        mapper.enable(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY);

        // JSON contains an unknown enum value "UNKNOWN" which should resolve to null
        // and then be skipped due to contentNulls = SKIP.
        // Fixed JSON structure to match BeanWithEnumList (was causing MismatchedInput before)
        String json = "{ \"statuses\": \"UNKNOWN\" }";

        BeanWithEnumList result = mapper.readValue(json, BeanWithEnumList.class);

        // The list should not be null, but should be empty because the single value was null and skipped
        assertNotNull(result.statuses);
        assertEquals(0, result.statuses.size());
    }

    @Test
    public void testSkipNullsFromUnknownEnumSingleValueMixed() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL);
        mapper.enable(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY);

        // JSON contains a valid enum value
        // Fixed JSON structure to match BeanWithEnumList
        String json = "{ \"statuses\": \"OK\" }";

        BeanWithEnumList result = mapper.readValue(json, BeanWithEnumList.class);

        assertNotNull(result.statuses);
        assertEquals(1, result.statuses.size());
        assertEquals(StatusEnum.OK, result.statuses.get(0));
    }

    // --- Test for _deserializeWithObjectId path ---

    @JsonIdentityInfo(generator = ObjectIdGenerators.PropertyGenerator.class, property = "id")
    @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.PROPERTY, property = "@type")
    @JsonSubTypes({
        @JsonSubTypes.Type(value = SubItem.class, name = "Sub")
    })
    public static abstract class BaseItem {
        public String id;
    }

    public static class SubItem extends BaseItem {
        public String value;
        public SubItem() {}
        public SubItem(String id, String value) {
            this.id = id;
            this.value = value;
        }
    }

    public static class BeanWithIdentityList {
        @JsonSetter(contentNulls = Nulls.SKIP)
        public List<BaseItem> items;
    }

    @Test
    public void testSkipNullsFromInvalidSubtypeWithObjectId() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Disable fail on invalid subtype so invalid type becomes null
        mapper.disable(DeserializationFeature.FAIL_ON_INVALID_SUBTYPE);

        // JSON contains one valid subtype and one invalid subtype
        // The invalid one should resolve to null and be skipped
        String json = "{\"items\": [" +
                "{\"@type\": \"Sub\", \"id\": \"1\", \"value\": \"A\"}, " +
                "{\"@type\": \"InvalidType\", \"id\": \"2\"}" +
                "]}";

        BeanWithIdentityList result = mapper.readValue(json, BeanWithIdentityList.class);

        assertNotNull(result.items);
        // Only the valid SubItem should be present
        assertEquals(1, result.items.size());
        assertTrue(result.items.get(0) instanceof SubItem);
        assertEquals("1", result.items.get(0).id);
    }

    @Test
    public void testSkipNullsFromExplicitNullWithObjectId() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Tests explicit null token handling in _deserializeWithObjectId loop
        // Covers: if (t == JsonToken.VALUE_NULL) { if (_skipNullValues) continue; ... }

        String json = "{\"items\": [" +
                "{\"@type\": \"Sub\", \"id\": \"1\", \"value\": \"A\"}, " +
                "null" +
                "]}";

        BeanWithIdentityList result = mapper.readValue(json, BeanWithIdentityList.class);

        assertNotNull(result.items);
        // Explicit null should be skipped
        assertEquals(1, result.items.size());
        assertTrue(result.items.get(0) instanceof SubItem);
    }

    @Test
    public void testSkipNullsFromInvalidSubtypeWithObjectIdSingleValue() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(DeserializationFeature.FAIL_ON_INVALID_SUBTYPE);
        mapper.enable(DeserializationFeature.ACCEPT_SINGLE_VALUE_AS_ARRAY);

        // Single value (not array) for a collection with Identity Info.
        // This triggers _deserializeWithObjectId -> !isExpectedStartArrayToken() -> handleNonArray.
        // Covers uncovered line: return handleNonArray(p, ctxt, result); inside _deserializeWithObjectId
        // Invalid subtype -> null -> skipped.
        String json = "{ \"items\": {\"@type\": \"InvalidType\", \"id\": \"2\"} }";

        BeanWithIdentityList result = mapper.readValue(json, BeanWithIdentityList.class);

        assertNotNull(result.items);
        assertEquals(0, result.items.size());
    }
}

