package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.*;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Test for [databind#736] - Fix REQUIRE_SETTERS_FOR_GETTERS taking no effect
 * Tests that couldDeserialize() properly checks field visibility
 */
public class POJOPropertyBuilder736Test {

    /**
     * Test class with a read-only property (getter only) and a read-write property (getter + setter)
     */
    public static class DataWithReadOnlyProperty {
        private int readonly = 1;
        private int readwrite = 2;

        public int getReadonly() {
            return readonly;
        }

        public int getReadwrite() {
            return readwrite;
        }

        public void setReadwrite(int readwrite) {
            this.readwrite = readwrite;
        }
    }

    /**
     * Test that REQUIRE_SETTERS_FOR_GETTERS excludes properties with only getters
     */
    @Test
    public void testRequireSettersForGettersExcludesReadOnlyProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);

        DataWithReadOnlyProperty data = new DataWithReadOnlyProperty();
        String json = mapper.writeValueAsString(data);

        // readonly should NOT be included (only has getter, no setter, private field not visible for deserialization)
        assertFalse("readonly property should be excluded when REQUIRE_SETTERS_FOR_GETTERS is enabled", 
                    json.contains("readonly"));

        // readwrite SHOULD be included (has both getter and setter)
        assertTrue("readwrite property should be included when it has both getter and setter", 
                   json.contains("readwrite"));

        // Verify the exact expected output
        assertEquals("{\"readwrite\":2}", json);
    }

    /**
     * Test that without REQUIRE_SETTERS_FOR_GETTERS, both properties are included
     */
    @Test
    public void testRequireSettersForGettersDisabled() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.disable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);

        DataWithReadOnlyProperty data = new DataWithReadOnlyProperty();
        String json = mapper.writeValueAsString(data);

        // Both properties should be included when feature is disabled
        assertTrue("readonly property should be included when REQUIRE_SETTERS_FOR_GETTERS is disabled", 
                   json.contains("readonly"));
        assertTrue("readwrite property should be included", 
                   json.contains("readwrite"));
    }

    /**
     * Test class with only getter (no setter) to verify it's excluded
     */
    public static class ReadOnlyClass {
        private int value = 42;

        public int getValue() {
            return value;
        }
    }

    /**
     * Test that a class with only getters is excluded when REQUIRE_SETTERS_FOR_GETTERS is enabled.
     * This test verifies the fix for databind#736 where private fields should not count 
     * towards deserialization capability if they are not visible.
     * Note: FAIL_ON_EMPTY_BEANS is disabled to allow verification of empty output.
     */
    @Test
    public void testReadOnlyClassExcluded() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);
        // Disable FAIL_ON_EMPTY_BEANS to avoid exception when no properties are serializable
        // This fixes the original test failure where InvalidDefinition was thrown
        mapper.disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);

        ReadOnlyClass data = new ReadOnlyClass();
        String json = mapper.writeValueAsString(data);

        // Should be empty since no setters and private field is not visible for deserialization
        assertEquals("Properties with only getters should be excluded resulting in empty bean", 
                     "{}", json);
    }

    /**
     * Test class with public field and getter (no setter).
     * Used to verify that visible fields DO allow deserialization capability.
     */
    public static class PublicFieldClass {
        public int value = 42;

        public int getValue() {
            return value;
        }
    }

    /**
     * Test that a class with a visible field (public) and getter is included,
     * even without a setter, because the field makes it deserializable.
     * This covers the 'true' branch of the _anyVisible(_fields) check added in the patch.
     */
    @Test
    public void testPublicFieldClassIncluded() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);

        PublicFieldClass data = new PublicFieldClass();
        String json = mapper.writeValueAsString(data);

        // Should include the property because the public field is visible and allows deserialization
        assertTrue("Properties with visible fields should be included even without setters", 
                   json.contains("value"));
        assertEquals("{\"value\":42}", json);
    }

    /**
     * Test class with both getter and setter to verify it's included
     */
    public static class ReadWriteClass {
        private int value = 42;

        public int getValue() {
            return value;
        }

        public void setValue(int value) {
            this.value = value;
        }
    }

    /**
     * Test that a class with both getter and setter is included
     */
    @Test
    public void testReadWriteClassIncluded() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(MapperFeature.REQUIRE_SETTERS_FOR_GETTERS);

        ReadWriteClass data = new ReadWriteClass();
        String json = mapper.writeValueAsString(data);

        // Should include the property since it has both getter and setter
        assertTrue("Properties with both getter and setter should be included", 
                   json.contains("value"));
        assertEquals("{\"value\":42}", json);
    }
}

