package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.*;

public class ObjectNodeFindValuesTest {

    private final ObjectMapper mapper = new ObjectMapper();

    @Test
    public void testFindValuesFindsAllMatchesAtDifferentLevels() throws Exception {
        // Create a JSON structure with multiple "target" fields at different levels
        // This test verifies the fix for #4229 where nested matches were missing
        String json = "{" +
            "\"target\": \"value1\"," +
            "\"object1\": {" +
            "  \"target\": \"value2\"," +
            "  \"nested\": {" +
            "    \"target\": \"value3\"" +
            "  }" +
            "}," +
            "\"object2\": {" +
            "  \"target\": \"value4\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<JsonNode> results = rootNode.findValues("target");

        // Should find all 4 "target" fields (root, object1, nested, object2)
        assertNotNull(results);
        assertEquals(4, results.size());
        assertEquals("value1", results.get(0).asText());
        assertEquals("value2", results.get(1).asText());
        assertEquals("value3", results.get(2).asText());
        assertEquals("value4", results.get(3).asText());
    }

    @Test
    public void testFindValuesAsTextFindsAllMatches() throws Exception {
        String json = "{" +
            "\"target\": \"value1\"," +
            "\"object1\": {" +
            "  \"target\": \"value2\"" +
            "}," +
            "\"object2\": {" +
            "  \"target\": \"value3\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<String> results = rootNode.findValuesAsText("target");

        assertNotNull(results);
        assertEquals(3, results.size());
        assertTrue(results.contains("value1"));
        assertTrue(results.contains("value2"));
        assertTrue(results.contains("value3"));
    }

    @Test
    public void testFindParentsFindsAllMatches() throws Exception {
        String json = "{" +
            "\"target\": \"value1\"," +
            "\"object1\": {" +
            "  \"target\": \"value2\"" +
            "}," +
            "\"object2\": {" +
            "  \"target\": \"value3\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<JsonNode> results = rootNode.findParents("target");

        // Should find 3 parent nodes (root, object1, object2)
        assertNotNull(results);
        assertEquals(3, results.size());
    }

    @Test
    public void testFindValuesWithNullList() throws Exception {
        String json = "{" +
            "\"target\": \"value1\"," +
            "\"other\": {" +
            "  \"target\": \"value2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<JsonNode> results = rootNode.findValues("target", null);

        assertNotNull(results);
        assertEquals(2, results.size());
    }

    @Test
    public void testFindValuesWithExistingList() throws Exception {
        String json = "{" +
            "\"target\": \"value1\"," +
            "\"other\": {" +
            "  \"target\": \"value2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<JsonNode> existingList = new ArrayList<>();
        existingList.add(mapper.readTree("\"existing\""));

        List<JsonNode> results = rootNode.findValues("target", existingList);

        assertNotNull(results);
        assertEquals(3, results.size()); // existing + 2 targets
        assertEquals("existing", results.get(0).asText());
    }

    @Test
    public void testFindValuesNoMatches() throws Exception {
        String json = "{" +
            "\"other\": \"value1\"," +
            "\"object1\": {" +
            "  \"different\": \"value2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<JsonNode> results = rootNode.findValues("target");

        // Fixed assertion: API returns empty list instead of null when no matches found
        // This aligns with the actual behavior observed after patching
        assertNotNull(results);
        assertEquals(0, results.size());
    }

    @Test
    public void testFindValuesAsTextNoMatches() throws Exception {
        String json = "{" +
            "\"other\": \"value1\"," +
            "\"object1\": {" +
            "  \"different\": \"value2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<String> results = rootNode.findValuesAsText("target");

        // Ensure consistent behavior with findValues
        assertNotNull(results);
        assertEquals(0, results.size());
    }

    @Test
    public void testFindParentsNoMatches() throws Exception {
        String json = "{" +
            "\"other\": \"value1\"," +
            "\"object1\": {" +
            "  \"different\": \"value2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<JsonNode> results = rootNode.findParents("target");

        // Ensure consistent behavior with findValues
        assertNotNull(results);
        assertEquals(0, results.size());
    }

    @Test
    public void testFindValuesWithNestedObjectsHavingSamePropertyName() throws Exception {
        // Test case specifically for issue #4229
        String json = "{" +
            "\"name\": \"root\"," +
            "\"object1\": {" +
            "  \"name\": \"obj1\"," +
            "  \"child\": {" +
            "    \"name\": \"child1\"" +
            "  }" +
            "}," +
            "\"object2\": {" +
            "  \"name\": \"obj2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<JsonNode> results = rootNode.findValues("name");

        // Should find all 4 "name" fields (root, obj1, child1, obj2)
        assertNotNull(results);
        assertEquals(4, results.size());

        List<String> values = new ArrayList<>();
        for (JsonNode node : results) {
            values.add(node.asText());
        }
        assertTrue(values.contains("root"));
        assertTrue(values.contains("obj1"));
        assertTrue(values.contains("child1"));
        assertTrue(values.contains("obj2"));
    }

    @Test
    public void testFindParentsWithNestedObjectsHavingSamePropertyName() throws Exception {
        String json = "{" +
            "\"name\": \"root\"," +
            "\"object1\": {" +
            "  \"name\": \"obj1\"" +
            "}," +
            "\"object2\": {" +
            "  \"name\": \"obj2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<JsonNode> results = rootNode.findParents("name");

        // Should find 3 parent nodes (root, object1, object2)
        assertNotNull(results);
        assertEquals(3, results.size());
    }

    @Test
    public void testFindValuesAsTextWithNullList() throws Exception {
        String json = "{" +
            "\"target\": \"value1\"," +
            "\"other\": {" +
            "  \"target\": \"value2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        List<String> results = rootNode.findValuesAsText("target", null);

        assertNotNull(results);
        assertEquals(2, results.size());
    }

    @Test
    public void testFindParentSingleMatch() throws Exception {
        String json = "{" +
            "\"target\": \"value1\"," +
            "\"other\": {" +
            "  \"different\": \"value2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);
        JsonNode result = rootNode.findParent("target");

        assertNotNull(result);
        assertTrue(result.isObject());
        assertEquals(rootNode, result);
    }
}

