import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Test for verifying that _externalTypeIdHandler is correctly preserved
 * in BeanDeserializerBase copy constructors when using @JsonIgnoreProperties
 * with @JsonTypeInfo(include = JsonTypeInfo.As.EXTERNAL_PROPERTY).
 * 
 * Optimized to:
 * 1. Fix class hierarchy to resolve InvalidTypeId errors.
 * 2. Cover @JsonIgnoreProperties on field (triggers ignorableProps constructor).
 * 3. Cover @JsonIdentityInfo (triggers ObjectIdReader constructor).
 * 4. Cover @JsonIgnoreProperties on class (triggers ignoreAllUnknown constructor).
 */
public class BeanDeserializerBaseExternalTypeIdTest {

    // Parent class with @JsonIgnoreProperties on child field
    // This triggers BeanDeserializerBase(BeanDeserializerBase src, Set<String> ignorableProps, ...)
    static class Parent {
        @JsonIgnoreProperties(ignoreUnknown = true)
