 * in BeanDeserializerBase copy constructors, specifically when @JsonIgnoreProperties
 * is used alongside @JsonTypeInfo with As.EXTERNAL_PROPERTY.
 * 
 * This test reproduces the issue where deserialization fails when a parent class field 
 * has @JsonIgnoreProperties and the child class has a polymorphic field using EXTERNAL_PROPERTY.
 * The bug was caused by _externalTypeIdHandler being dropped during copy construction
 * triggered by withByNameInclusion() or withIgnoreAllUnknown().
 */
public class ExternalTypeIdHandlerCopyTest {

    public static class Parent {
        // Annotation on field ensures Child deserializer is configured to ignore "ignoredProp".
        // This triggers withByNameInclusion() -> BeanDeserializerBase(src, ignorableProps, includableProps)
        // which was missing the _externalTypeIdHandler copy in the buggy version.
        @JsonIgnoreProperties({"ignoredProp"})
        public Child child;
    }

    public static class Child {
        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "childType")
        @JsonSubTypes({
            @JsonSubTypes.Type(value = SubChildA.class, name = "A"),
            @JsonSubTypes.Type(value = SubChildB.class, name = "B")
        })
        public SubChild subChild;
    }

    public static interface SubChild {}

    public static class SubChildA implements SubChild {}
    public static class SubChildB implements SubChild {}

    @Test
    public void testExternalTypeIdHandlerWithJsonIgnoreProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // ignoredProp should be ignored due to @JsonIgnoreProperties on Parent.child
        // childType should be used to resolve subChild type via ExternalTypeHandler
        String json = "{\"child\":{\"ignoredProp\": \"foo\", \"childType\":\"A\", \"subChild\": {}}}";

        Parent result = mapper.readValue(json, Parent.class);

        assertNotNull("Result should not be null", result);
        assertNotNull("Child should not be null", result.child);
        assertNotNull("SubChild should not be null", result.child.subChild);
        assertTrue("SubChild should be instance of SubChildA", result.child.subChild instanceof SubChildA);
    }

    // Additional test case to cover the ignoreAllUnknown copy constructor path
    // This triggers BeanDeserializerBase(src, boolean ignoreAllUnknown) which was also patched.
    public static class ParentWithIgnoreUnknown {
        @JsonIgnoreProperties(ignoreUnknown = true)
        public Child child;
