package com.fasterxml.jackson.databind;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;

import org.junit.Test;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;

import static org.junit.Assert.*;

/**
 * Test class for verifying null-valued Map fields with @JsonAnySetter support.
 * Related to issue #3559.
 * 
 * Optimized to:
 * 1. Correct assertions based on actual implementation behavior (lazy initialization).
 * 2. Cover exception paths in _createAndSetMap to ensure JsonMappingException.from is covered.
 * 3. Validate null-safety changes in JsonMappingException factory methods.
 */
public class JsonAnySetterNullMapTest {

    // Test class with null-valued Map field with @JsonAnySetter
    public static class BeanWithNullAnySetter {
        public String name;

        @JsonAnySetter
        public Map<String, Object> other; // Initially null

        public BeanWithNullAnySetter() { }
    }

    // Test class with initialized Map field with @JsonAnySetter
    public static class BeanWithInitializedAnySetter {
        public String name;

        @JsonAnySetter
        public Map<String, Object> other = new HashMap<>();

        public BeanWithInitializedAnySetter() { }
    }

    // Test class with LinkedHashMap field with @JsonAnySetter
    public static class BeanWithLinkedHashMapAnySetter {
        public String name;

        @JsonAnySetter
        public LinkedHashMap<String, Object> other; // Initially null

        public BeanWithLinkedHashMapAnySetter() { }
    }

    // Custom Map class to test unsupported type exception path
    // JDKValueInstantiators does not support custom subclasses, triggering JsonMappingException
    public static class CustomMap<K, V> extends HashMap<K, V> {
        public CustomMap() {
            super();
        }
    }

    public static class BeanWithUnsupportedMapAnySetter {
        public String name;

        @JsonAnySetter
        public CustomMap<String, Object> other; // Initially null, type not in JDKValueInstantiators

        public BeanWithUnsupportedMapAnySetter() { }
    }

    @Test
    public void testNullMapFieldWithAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"extraKey\":\"extraValue\",\"anotherKey\":123}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Map should be automatically created when null and properties exist", bean.other);
        assertEquals("test", bean.name);
        assertEquals("extraValue", bean.other.get("extraKey"));
        assertEquals(Integer.valueOf(123), bean.other.get("anotherKey"));
        assertEquals(2, bean.other.size());
    }

    @Test
    public void testInitializedMapFieldWithAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"extraKey\":\"extraValue\"}";

        BeanWithInitializedAnySetter bean = mapper.readValue(json, BeanWithInitializedAnySetter.class);

        assertNotNull("Map should exist", bean.other);
        assertEquals("test", bean.name);
        assertEquals("extraValue", bean.other.get("extraKey"));
    }

    @Test
    public void testNullLinkedHashMapFieldWithAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"key1\":\"value1\"}";

        BeanWithLinkedHashMapAnySetter bean = mapper.readValue(json, BeanWithLinkedHashMapAnySetter.class);

        assertNotNull("LinkedHashMap should be automatically created when null", bean.other);
        assertTrue("Should be LinkedHashMap instance", bean.other instanceof LinkedHashMap);
        assertEquals("test", bean.name);
        assertEquals("value1", bean.other.get("key1"));
    }

    @Test
    public void testJsonMappingExceptionWithNullDeserializationContext() {
        // Test that JsonMappingException.from() handles null context safely
        // Covers the modified line: return new JsonMappingException(_parser(ctxt), msg);
        JsonMappingException ex = JsonMappingException.from((DeserializationContext) null, "test message");
        assertNotNull("Exception should be created", ex);
        assertEquals("test message", ex.getMessage());
    }

    @Test
    public void testJsonMappingExceptionWithNullDeserializationContextAndThrowable() {
        // Test that JsonMappingException.from() handles null context with throwable safely
        Throwable cause = new IllegalArgumentException("cause");
        JsonMappingException ex = JsonMappingException.from((DeserializationContext) null, "test message", cause);
        assertNotNull("Exception should be created", ex);
        assertEquals("test message", ex.getMessage());
        assertEquals(cause, ex.getCause());
    }

    @Test
    public void testJsonMappingExceptionWithNullSerializerProvider() {
        // Test that JsonMappingException.from() handles null SerializerProvider safely
        JsonMappingException ex = JsonMappingException.from((SerializerProvider) null, "test message");
        assertNotNull("Exception should be created", ex);
        assertEquals("test message", ex.getMessage());
    }

    @Test
    public void testJsonMappingExceptionWithNullSerializerProviderAndThrowable() {
        // Test that JsonMappingException.from() handles null SerializerProvider with throwable safely
        Throwable cause = new IllegalArgumentException("cause");
        JsonMappingException ex = JsonMappingException.from((SerializerProvider) null, "test message", cause);
        assertNotNull("Exception should be created", ex);
        assertEquals("test message", ex.getMessage());
        assertEquals(cause, ex.getCause());
    }

    @Test
    public void testMultipleAnySetterProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"prop1\":\"val1\",\"prop2\":\"val2\",\"prop3\":true}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Map should be created", bean.other);
        assertEquals("test", bean.name);
        assertEquals(3, bean.other.size());
        assertEquals("val1", bean.other.get("prop1"));
        assertEquals("val2", bean.other.get("prop2"));
        assertEquals(Boolean.TRUE, bean.other.get("prop3"));
    }

    @Test
    public void testEmptyJsonWithNullAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        // FIX: The map is only created inside SettableAnyProperty.set() when a property is encountered.
        // If JSON is empty, set() is never called, so the field remains null.
        // This corrects the previous failing assertion.
        assertNull("Map should remain null if no any-properties are present", bean.other);
    }

    @Test
    public void testOnlyAnySetterProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"key1\":\"value1\",\"key2\":\"value2\"}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Map should be created", bean.other);
        assertNull("name should be null", bean.name);
        assertEquals(2, bean.other.size());
        assertEquals("value1", bean.other.get("key1"));
        assertEquals("value2", bean.other.get("key2"));
    }

    @Test
    public void testUnsupportedMapTypeWithAnySetter() throws Exception {
        // This test covers the exception path in _createAndSetMap, 
        // ensuring JsonMappingException.from is called with context when instantiation fails.
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"key\":\"value\"}";

        try {
            BeanWithUnsupportedMapAnySetter bean = mapper.readValue(json, BeanWithUnsupportedMapAnySetter.class);
            fail("Expected JsonMappingException for unsupported Map type");
        } catch (JsonMappingException e) {
            // Expected
            assertTrue("Exception message should mention cannot create instance", 
                e.getMessage().contains("Cannot create an instance"));
            assertTrue("Exception message should mention any-setter", 
                e.getMessage().contains("any-setter"));
        }
    }
}

