package com.fasterxml.jackson.databind.node;

import org.junit.Test;
import static org.junit.Assert.*;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.core.JsonPointer;

/**
 * Unit tests for the withObject(String) method in ObjectNode.
 * Tests the behavior change that allows both JsonPointer expressions
 * and simple property names as arguments.
 */
public class ObjectNodeWithObjectTest {

    @Test
    public void testWithObjectSimplePropertyName() {
        // Test that simple property names (not starting with '/') work
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        ObjectNode child = root.withObject("foo");

        assertNotNull("Should return non-null ObjectNode", child);
        assertTrue("Should be an ObjectNode", child.isObject());
        assertTrue("Root should contain the property", root.has("foo"));
        assertSame("Should return the same node on subsequent calls", 
                   child, root.withObject("foo"));
    }

    @Test
    public void testWithObjectJsonPointerExpression() {
        // Test that valid JsonPointer expressions (starting with '/') work
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        ObjectNode nested = root.withObject("/foo/bar");

        assertNotNull("Should return non-null ObjectNode", nested);
        assertTrue("Should be an ObjectNode", nested.isObject());
        assertTrue("Root should contain 'foo'", root.has("foo"));
        assertTrue("Foo should contain 'bar'", root.path("foo").has("bar"));
        assertSame("Should return the same node on subsequent calls", 
                   nested, root.withObject("/foo/bar"));
    }

    @Test
    public void testWithObjectEmptyString() {
        // Test that empty string (valid JsonPointer) returns current node
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        root.put("existing", "value");

        ObjectNode result = root.withObject("");

        assertSame("Empty string should return the same node", root, result);
        assertTrue("Should preserve existing content", result.has("existing"));
    }

    @Test
    public void testWithObjectCreatesIntermediateNodes() {
        // Test that nested JsonPointer creates intermediate nodes
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        ObjectNode deep = root.withObject("/a/b/c");

        assertNotNull("Should return non-null ObjectNode", deep);
        assertTrue("Should create intermediate 'a' node", root.has("a"));
        assertTrue("Should create intermediate 'b' node", root.path("a").has("b"));
        assertTrue("Should create final 'c' node", root.path("a").path("b").has("c"));

        // Verify we can add content to the deep node
        deep.put("key", "value");
        assertEquals("Should be able to add content", "value", 
                    root.path("a").path("b").path("c").path("key").asText());
    }

    @Test
    public void testWithObjectVersusWithObjectProperty() {
        // Test that withObject with property name behaves like withObjectProperty
        ObjectNode root1 = JsonNodeFactory.instance.objectNode();
        ObjectNode root2 = JsonNodeFactory.instance.objectNode();

        ObjectNode node1 = root1.withObject("prop");
        ObjectNode node2 = root2.withObjectProperty("prop");

        // Use same value for proper comparison
        String testValue = "testValue";
        node1.put("test", testValue);
        node2.put("test", testValue);

        assertEquals("Both should create similar structure", 
                    root1.toString(), root2.toString());
    }

    @Test
    public void testWithObjectVersusWithObjectJsonPointer() {
        // Test that withObject with JsonPointer behaves like withObject(JsonPointer)
        ObjectNode root1 = JsonNodeFactory.instance.objectNode();
        ObjectNode root2 = JsonNodeFactory.instance.objectNode();

        ObjectNode node1 = root1.withObject("/foo/bar");
        ObjectNode node2 = root2.withObject(JsonPointer.compile("/foo/bar"));

        // Use same value for proper comparison
        String testValue = "testValue";
        node1.put("test", testValue);
        node2.put("test", testValue);

        assertEquals("Both should create similar structure", 
                    root1.toString(), root2.toString());
    }

    @Test
    public void testWithObjectPropertyNameWithSpecialChars() {
        // Test property names that might look like JsonPointer but aren't
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Property name without leading slash
        ObjectNode child = root.withObject("foo/bar");

        assertNotNull("Should return non-null ObjectNode", child);
        assertTrue("Root should contain the literal property name 'foo/bar'", 
                  root.has("foo/bar"));
        assertFalse("Should NOT create nested structure", root.has("foo"));
    }

    @Test
    public void testWithObjectConsistencyWithWithArray() {
        // Test that withObject behaves consistently with withArray
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Both should accept simple property names
        ObjectNode objNode = root.withObject("obj");
        ArrayNode arrNode = root.withArray("arr");

        assertNotNull("withObject should work with property name", objNode);
        assertNotNull("withArray should work with property name", arrNode);
        assertTrue("Root should have both properties", 
                  root.has("obj") && root.has("arr"));
    }

    @Test
    public void testWithObjectMultipleLevels() {
        // Test multiple levels of nesting with mixed property names and pointers
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // First level with property name
        ObjectNode level1 = root.withObject("level1");
        level1.put("key1", "value1");

        // Second level with JsonPointer from root
        ObjectNode level2 = root.withObject("/level1/level2");
        level2.put("key2", "value2");

        // Third level with property name from level2
        ObjectNode level3 = level2.withObject("level3");
        level3.put("key3", "value3");

        // Verify all levels exist
        assertEquals("value1", root.path("level1").path("key1").asText());
        assertEquals("value2", root.path("level1").path("level2").path("key2").asText());
        assertEquals("value3", root.path("level1").path("level2").path("level3").path("key3").asText());
    }

    @Test
    public void testWithObjectOnArrayNodeThrowsException() {
        // Test that ArrayNode.withObject(String) throws UnsupportedOperationException
        ArrayNode arrayNode = JsonNodeFactory.instance.arrayNode();

        try {
            arrayNode.withObject("test");
            fail("Should throw UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            assertTrue("Exception message should mention ArrayNode", 
                      e.getMessage().contains("ArrayNode"));
        }
    }

    @Test
    public void testWithObjectReturnsSameInstance() {
        // Test that repeated calls return the same instance
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        ObjectNode first = root.withObject("test");
        ObjectNode second = root.withObject("test");

        assertSame("Should return same instance", first, second);
    }

    @Test
    public void testWithObjectWithJsonPointerReturnsSameInstance() {
        // Test that repeated calls with JsonPointer return the same instance
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        ObjectNode first = root.withObject("/test/path");
        ObjectNode second = root.withObject("/test/path");

        assertSame("Should return same instance", first, second);
    }

    @Test
    public void testWithObjectPropertyThatExists() {
        // Test withObject when property already exists as ObjectNode
        ObjectNode root = JsonNodeFactory.instance.objectNode();
        ObjectNode existing = root.putObject("existing");
        existing.put("key", "value");

        ObjectNode retrieved = root.withObject("existing");

        assertSame("Should return existing node", existing, retrieved);
        assertEquals("Should preserve existing content", "value", 
                    retrieved.path("key").asText());
    }

    @Test
