public class TypeParserGuardrailsTest {

    private final TypeFactory _factory = TypeFactory.defaultInstance();

    @Test
    public void testNormalTypeParsing() {
        TypeParser parser = new TypeParser(_factory);
        JavaType type = parser.parse("java.util.Map<java.lang.String, java.lang.Integer>");
        assertNotNull(type);
    }

    @Test
    public void testTypeLengthExceedsMax() {
        TypeParser parser = new TypeParser(_factory);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 65000; i++) {
            sb.append("a");
        }
        String longType = sb.toString();

        try {
            parser.parse(longType);
            fail("Expected IllegalArgumentException for type string exceeding max length");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention 'too long': " + e.getMessage(), 
                       e.getMessage().contains("too long"));
            assertTrue("Error message should mention max length 64000: " + e.getMessage(), 
                       e.getMessage().contains("64000"));
            // Since input length (65000) > 1000, _quoteTruncated should truncate the message
            assertTrue("Error message should contain truncation indicator for long input: " + e.getMessage(),
                       e.getMessage().contains("[truncated"));
            // Fix assertion to match the typo in source code ('charaters' instead of 'characters')
            assertTrue("Error message should mention 'charaters' (typo in source): " + e.getMessage(), 
                       e.getMessage().contains("charaters"));
        }
    }

    @Test
    public void testNestingDepthExceedsMax() {
        TypeParser parser = new TypeParser(_factory);
        StringBuilder sb = new StringBuilder();
        // Construct a type with nesting depth > 1000 to trigger the guardrail
        // MAX_TYPE_NESTING is 1000. We need to exceed this.
        for (int i = 0; i < 1005; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < 1005; i++) {
            sb.append(">");
        }
        String nestedType = sb.toString();

        try {
            parser.parse(nestedType);
            fail("Expected IllegalArgumentException for type exceeding max nesting");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention 'too deeply nested': " + e.getMessage(), 
                       e.getMessage().contains("too deeply nested"));
            assertTrue("Error message should mention max nesting 1000: " + e.getMessage(), 
                       e.getMessage().contains("1000"));
        }
    }

    @Test
    public void testErrorMessageTruncationForLongInput() {
        TypeParser parser = new TypeParser(_factory);
        StringBuilder sb = new StringBuilder();
        // Create an invalid type string longer than 1000 chars to trigger truncation in error message
        for (int i = 0; i < 1500; i++) {
            sb.append("x");
        }
        String longInvalidType = sb.toString();

        try {
            parser.parse(longInvalidType);
            fail("Expected IllegalArgumentException for invalid type");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should contain truncation indicator: " + e.getMessage(), 
                       e.getMessage().contains("[truncated"));
            // Fix assertion to match the typo in source code ('charaters' instead of 'characters')
            assertTrue("Error message should mention 'charaters' (typo in source): " + e.getMessage(), 
                       e.getMessage().contains("charaters"));
        }
    }

    @Test
    public void testErrorMessageForShortInvalidInput() {
        TypeParser parser = new TypeParser(_factory);
        String shortInvalidType = "invalid<type>";

        try {
            parser.parse(shortInvalidType);
            fail("Expected IllegalArgumentException for invalid type");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should contain the input in quotes: " + e.getMessage(), 
                       e.getMessage().contains("'invalid<type>'"));
            assertFalse("Error message should not contain truncation for short input: " + e.getMessage(), 
                        e.getMessage().contains("[truncated"));
        }
    }

    @Test
    public void testValidNestedTypeWithinLimit() {
        TypeParser parser = new TypeParser(_factory);
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.List<");
        for (int i = 0; i < 10; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < 10; i++) {
            sb.append(">");
        }
        sb.append(">");
        String nestedType = sb.toString();

        JavaType type = parser.parse(nestedType);
        assertNotNull("Valid nested type should parse successfully", type);
    }

    @Test
    public void testTypeLengthAtMaxLimit() {
        TypeParser parser = new TypeParser(_factory);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 64000; i++) {
            sb.append("a");
        }
        String maxType = sb.toString();

        try {
            parser.parse(maxType);
            // Parsing might fail for other reasons (e.g. invalid class name 'a...'), 
            // but it should NOT fail due to the length guardrail.
        } catch (IllegalArgumentException e) {
            assertFalse("Should not fail due to length at max limit: " + e.getMessage(), 
                        e.getMessage().contains("too long"));
        }
    }
}

