package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.exc.MismatchedInputException;
import org.junit.Test;

import java.util.Date;

import static org.junit.Assert.*;

/**
 * Test class for CVE-2022-42003 fix - deep wrapper array nesting protection
 * with UNWRAP_SINGLE_VALUE_ARRAYS feature.
 */
public class StdDeserializerNestedArrayTest {

    private ObjectMapper createMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);
        return mapper;
    }

    @Test
    public void testNestedArrayRejectedForBoolean() throws Exception {
        ObjectMapper mapper = createMapper();

        // Single-level array should work
        Boolean result = mapper.readValue("[true]", Boolean.class);
        assertTrue(result);

        // Nested array should fail
        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("[[true]]", Boolean.class)
        );

        // Deeply nested array should fail
        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("[[[true]]]", Boolean.class)
        );
    }

    @Test
    public void testNestedArrayRejectedForInteger() throws Exception {
        ObjectMapper mapper = createMapper();

        // Single-level array should work
        Integer result = mapper.readValue("[42]", Integer.class);
        assertEquals(42, result.intValue());

        // Nested array should fail
        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("[[42]]", Integer.class)
        );
    }

    @Test
    public void testNestedArrayRejectedForLong() throws Exception {
        ObjectMapper mapper = createMapper();

        Long result = mapper.readValue("[123456789]", Long.class);
        assertEquals(123456789L, result.longValue());

        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("[[123456789]]", Long.class)
        );
    }

    @Test
    public void testNestedArrayRejectedForDouble() throws Exception {
        ObjectMapper mapper = createMapper();

        Double result = mapper.readValue("[3.14]", Double.class);
        assertEquals(3.14, result, 0.001);

        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("[[3.14]]", Double.class)
        );
    }

    @Test
    public void testNestedArrayRejectedForFloat() throws Exception {
        ObjectMapper mapper = createMapper();

        Float result = mapper.readValue("[2.5]", Float.class);
        assertEquals(2.5f, result, 0.001f);

        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("[[2.5]]", Float.class)
        );
    }

    @Test
    public void testNestedArrayRejectedForByte() throws Exception {
        ObjectMapper mapper = createMapper();

        Byte result = mapper.readValue("[10]", Byte.class);
        assertEquals((byte) 10, result.byteValue());

        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("[[10]]", Byte.class)
        );
    }

    @Test
    public void testNestedArrayRejectedForShort() throws Exception {
        ObjectMapper mapper = createMapper();

        Short result = mapper.readValue("[100]", Short.class);
        assertEquals((short) 100, result.shortValue());

        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("[[100]]", Short.class)
        );
    }

    // Tests for Primitive Fields in POJOs (Covering _parse...Primitive methods)
    // These tests were failing because the JSON input was targeting the root object 
    // instead of the primitive field. Fixed to use {"value": ...} format.
    @Test
    public void testNestedArrayRejectedForPrimitiveBoolean() throws Exception {
        ObjectMapper mapper = createMapper();

        // Single-level array should work for primitive field
        BooleanWrapper wrapper = mapper.readValue("{\"value\":[true]}", BooleanWrapper.class);
        assertTrue(wrapper.value);

        // Nested array should fail for primitive field
        // This covers _parseBooleanPrimitive nested array check
        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("{\"value\":[[true]]}", BooleanWrapper.class)
        );
    }

    @Test
    public void testNestedArrayRejectedForPrimitiveInt() throws Exception {
        ObjectMapper mapper = createMapper();

        IntWrapper wrapper = mapper.readValue("{\"value\":[42]}", IntWrapper.class);
        assertEquals(42, wrapper.value);

        // This covers _parseIntPrimitive nested array check (UNCOVERED line in analysis)
        assertThrows(MismatchedInputException.class, () -> 
            mapper.readValue("{\"value\":[[42]]}", IntWrapper.class)
        );
    }

