package com.fasterxml.jackson.databind;

import java.util.LinkedHashMap;
import java.util.Map;

import org.junit.Test;

import com.fasterxml.jackson.annotation.JsonAnySetter;
import com.fasterxml.jackson.databind.exc.InvalidDefinitionException;

import static org.junit.Assert.*;

public class AnySetterNullMapTest {

    static class BeanWithNullAnySetter {
        public String name;

        @JsonAnySetter
        public Map<String, Object> other;  // Initially null

        public BeanWithNullAnySetter() { }
    }

    static class BeanWithInitializedAnySetter {
        public String name;

        @JsonAnySetter
        public Map<String, Object> other = new LinkedHashMap<>();

        public BeanWithInitializedAnySetter() { }
    }

    static class BeanWithLinkedHashMap {
        public String name;

        @JsonAnySetter
        public LinkedHashMap<String, Object> other;  // Initially null

        public BeanWithLinkedHashMap() { }
    }

    static class BeanWithCustomMap {
        public String name;

        @JsonAnySetter
        public CustomMap<String, Object> other;  // Custom Map type that cannot be instantiated

        public BeanWithCustomMap() { }
    }

    static class CustomMap<K, V> extends LinkedHashMap<K, V> {
        // Private constructor to prevent instantiation
        private CustomMap() {
            super();
        }
    }

    @Test
    public void testNullAnySetterMapGetsInitialized() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"extra1\":\"value1\",\"extra2\":\"value2\"}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Map should be initialized when extra properties exist", bean.other);
        assertEquals("test", bean.name);
        assertEquals("value1", bean.other.get("extra1"));
        assertEquals("value2", bean.other.get("extra2"));
        assertEquals(2, bean.other.size());
    }

    @Test
    public void testInitializedAnySetterMapStillWorks() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"extra1\":\"value1\"}";

        BeanWithInitializedAnySetter bean = mapper.readValue(json, BeanWithInitializedAnySetter.class);

        assertNotNull("Map should exist", bean.other);
        assertEquals("test", bean.name);
        assertEquals("value1", bean.other.get("extra1"));
    }

    @Test
    public void testLinkedHashMapAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"extra\":\"value\"}";

        BeanWithLinkedHashMap bean = mapper.readValue(json, BeanWithLinkedHashMap.class);

        assertNotNull("Map should be initialized", bean.other);
        assertTrue("Should be LinkedHashMap", bean.other instanceof LinkedHashMap);
        assertEquals("value", bean.other.get("extra"));
    }

    @Test
    public void testNullContextInJsonMappingException() throws Exception {
        // Test that JsonMappingException.from() handles null context safely
        // This tests the _parser() helper method added in the patch
        // Covers: public static JsonMappingException from(DeserializationContext ctxt, String msg, Throwable t)
        JsonMappingException ex = JsonMappingException.from((DeserializationContext) null, "Test message");
        assertNotNull("Exception should be created even with null context", ex);
        assertEquals("Test message", ex.getMessage());

        JsonMappingException exWithCause = JsonMappingException.from((DeserializationContext) null, "Test message", new RuntimeException("cause"));
        assertNotNull("Exception with cause should be created even with null context", exWithCause);
        assertEquals("Test message", exWithCause.getMessage());
        assertNotNull("Cause should be preserved", exWithCause.getCause());
    }

    @Test
    public void testNullContextInJsonMappingExceptionWithSerializerProvider() throws Exception {
        // Test that JsonMappingException.from() handles null SerializerProvider safely
        // This tests the _generator() helper method added in the patch
        JsonMappingException ex = JsonMappingException.from((SerializerProvider) null, "Test message");
        assertNotNull("Exception should be created even with null SerializerProvider", ex);
        assertEquals("Test message", ex.getMessage());

        JsonMappingException exWithCause = JsonMappingException.from((SerializerProvider) null, "Test message", new RuntimeException("cause"));
        assertNotNull("Exception with cause should be created even with null SerializerProvider", exWithCause);
        assertEquals("Test message", exWithCause.getMessage());
    }

    @Test
    public void testAnySetterWithComplexValues() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"number\":42,\"nested\":{\"key\":\"value\"},\"array\":[1,2,3]}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Map should be initialized", bean.other);
        assertEquals("test", bean.name);
        assertEquals(Integer.valueOf(42), bean.other.get("number"));
        assertNotNull("Nested object should be deserialized", bean.other.get("nested"));
        assertNotNull("Array should be deserialized", bean.other.get("array"));
    }

    @Test
    public void testAnySetterWithEmptyJson() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        // Map remains null if no 'any' properties are present (lazy initialization)
        // The patch initializes the map only when set() is called for an extra property
        assertNull("Map should remain null if no extra properties are present", bean.other);
        assertNull("Name should be null", bean.name);
    }

    @Test
    public void testAnySetterWithOnlyExtraProperties() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"extra1\":\"value1\",\"extra2\":\"value2\"}";

        BeanWithNullAnySetter bean = mapper.readValue(json, BeanWithNullAnySetter.class);

        assertNotNull("Map should be initialized", bean.other);
        assertNull("Name should be null", bean.name);
        assertEquals("value1", bean.other.get("extra1"));
        assertEquals("value2", bean.other.get("extra2"));
    }

    @Test
    public void testCustomMapAnySetterFails() throws Exception {
        // Test that unsupported Map types throw a clear JsonMappingException
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"extra\":\"value\"}";

        try {
            mapper.readValue(json, BeanWithCustomMap.class);
            fail("Expected JsonMappingException for unsupported Map type");
        } catch (JsonMappingException e) {
            // Verify the error message contains expected text from the patch
            assertTrue("Error message should mention 'any-setter'", e.getMessage().contains("any-setter"));
            assertTrue("Error message should mention the class name", e.getMessage().contains("CustomMap"));
        }
    }
}

