        public String name;

        @JsonAnySetter
        public HashMap<String, Object> extraProperties; // Initially null

        public BeanWithHashMapAnySetter() { }
    }

    // Test bean with SortedMap (interface, no default instantiator) and @JsonAnySetter
    public static class BeanWithSortedMapAnySetter {
        public String name;

        @JsonAnySetter
        public SortedMap<String, Object> extraProperties; // Initially null, interface type

        public BeanWithSortedMapAnySetter() { }
    }

    @Test
    public void testNullValuedMapFieldWithAnySetter() throws Exception {
        ObjectMapper mapper = new ObjectMapper();

        String json = "{\"name\":\"test\",\"extraKey\":\"extraValue\"}";

