        JsonMappingException ex1 = JsonMappingException.from((DeserializationContext) null, "test message");
        assertNotNull(ex1);
        assertEquals("test message", ex1.getMessage());

        JsonMappingException ex2 = JsonMappingException.from((DeserializationContext) null, "test message", new RuntimeException("cause"));
        assertNotNull(ex2);
