package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.util.EnumValues;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.core.SerializableString;
import org.junit.Test;
import static org.junit.Assert.*;

import java.util.ArrayList;
import java.util.List;

/**
 * Test for [databind#4355]: Jackson 2.16 fails attempting to obtain {@code ObjectWriter}
 * for an {@code Enum} of which some value returns null from {@code toString()}
 */
public class EnumValues4355Test {

    /**
     * Enum where one constant's toString() returns null.
     * This triggers the issue fixed in #4355.
     */
    public enum NullToStringEnum {
        ALPHA,
        UNDEFINED;

        @Override
        public String toString() {
            if (this == UNDEFINED) {
                return null;
            }
            return name();
        }
    }

    /**
     * Enum where all constants have normal toString() behavior.
     * Used as a control to ensure normal enums still work.
     */
    public enum NormalEnum {
        FOO,
        BAR;

        @Override
        public String toString() {
            return name();
        }
    }

    @Test
    public void testEnumWithNullToStringShouldNotThrowException() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        // Enable WRITE_ENUMS_USING_TO_STRING to ensure toString() is used for serialization.
        // Without this, Jackson uses name() by default, which would not trigger the 
        // specific toString() null handling logic during serialization output,
        // though the Writer creation still exercises the fix.
        mapper.enable(SerializationFeature.WRITE_ENUMS_USING_TO_STRING);

        // This should not throw IllegalStateException: Null String illegal for SerializedString
        // The fix in EnumValues.constructFromToString prevents this by coercing null to "".
        ObjectWriter writer = mapper.writerFor(NullToStringEnum.class);
        assertNotNull("ObjectWriter should be created successfully", writer);

        // Test serialization of ALPHA (normal toString)
        String alphaJson = writer.writeValueAsString(NullToStringEnum.ALPHA);
        assertEquals("\"ALPHA\"", alphaJson);

        // Test serialization of UNDEFINED (null toString, should be coerced to empty string)
        // This assertion validates the specific fix: null -> ""
        String undefinedJson = writer.writeValueAsString(NullToStringEnum.UNDEFINED);
        assertEquals("\"\"", undefinedJson);
    }

    @Test
    public void testNormalEnumStillWorks() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.WRITE_ENUMS_USING_TO_STRING);

        ObjectWriter writer = mapper.writerFor(NormalEnum.class);
        assertNotNull(writer);

        String fooJson = writer.writeValueAsString(NormalEnum.FOO);
        assertEquals("\"FOO\"", fooJson);

        String barJson = writer.writeValueAsString(NormalEnum.BAR);
        assertEquals("\"BAR\"", barJson);
    }

    @Test
    public void testEnumValuesConstructFromToStringWithNullToString() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        MapperConfig<?> config = mapper.getSerializationConfig();

        // Get AnnotatedClass from BeanDescription
        AnnotatedClass annotatedClass = mapper.getSerializationConfig().introspect(
            mapper.getTypeFactory().constructType(NullToStringEnum.class)
        ).getClassInfo();

        // This should not throw an exception even with null toString()
        // This directly covers the patched method EnumValues.constructFromToString
        EnumValues enumValues = EnumValues.constructFromToString(
            config,
            annotatedClass
        );

        assertNotNull(enumValues);
        assertEquals(2, enumValues.values().size());

        // Verify that the null toString() result was coerced to empty string.
        // The order of values() corresponds to the enum constant ordinals.
        List<SerializableString> values = new ArrayList<>(enumValues.values());

        // ALPHA (ordinal 0) -> "ALPHA"
        assertEquals("ALPHA", values.get(0).getValue());

        // UNDEFINED (ordinal 1) -> "" (coerced from null toString)
        // This assertion specifically validates the patch logic: if (name == null) { name = ""; }
        assertEquals("", values.get(1).getValue());
    }

    @Test
    public void testSerializationWithObjectMapper() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.WRITE_ENUMS_USING_TO_STRING);

        // Direct serialization should also work
        String alphaJson = mapper.writeValueAsString(NullToStringEnum.ALPHA);
        assertEquals("\"ALPHA\"", alphaJson);

        String undefinedJson = mapper.writeValueAsString(NullToStringEnum.UNDEFINED);
        assertEquals("\"\"", undefinedJson);
    }

    // Note: testDeserializationWithEmptyString was removed. 
    // The patch fixes serialization construction (EnumValues.constructFromToString).
    // Deserialization of empty string to Enum requires CoercionConfig which is 
    // outside the scope of this specific fix and caused test failures unrelated 
    // to the patch's primary goal.
}

