package com.fasterxml.jackson.databind;

import java.io.IOException;
import java.util.*;

import org.junit.Test;

import com.fasterxml.jackson.annotation.JsonAnySetter;

import static org.junit.Assert.*;

/**
 * Test class for verifying support of null-valued Map fields with @JsonAnySetter.
 * Related to issue #3559.
 * 
 * Optimized to:
 * 1. Fix failing test regarding empty JSON (lazy initialization behavior).
 * 2. Add coverage for unsupported Map types (exception path).
 * 3. Ensure JsonMappingException null-safety helpers are covered.
 */
public class AnySetterNullMapTest {

    /**
     * Test bean with null-initialized Map field annotated with @JsonAnySetter.
     */
    static class BeanWithNullAnySetter {
        public String name;

        @JsonAnySetter
        public Map<String, Object> extraProperties;  // intentionally not initialized

        public BeanWithNullAnySetter() { }
    }

    /**
     * Test bean with pre-initialized Map field annotated with @JsonAnySetter.
     */
    static class BeanWithInitializedAnySetter {
