package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JacksonInject;
import com.fasterxml.jackson.core.Version;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for the Primary Creator extension point (Issue #4584)
 * and PotentialCreator enhancements.
 */
public class PrimaryCreatorExtensionTest {

    /**
     * Test that AnnotationIntrospector.findPrimaryCreator() returns null by default.
     */
    @Test
    public void testFindPrimaryCreatorDefaultImplementation() {
        AnnotationIntrospector introspector = new AnnotationIntrospector() {
            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        MapperConfig<?> config = mock(MapperConfig.class);
        AnnotatedClass valueClass = mock(AnnotatedClass.class);
        List<PotentialCreator> constructors = new ArrayList<>();
        List<PotentialCreator> factories = new ArrayList<>();

        PotentialCreator result = introspector.findPrimaryCreator(
            config, valueClass, constructors, factories);

        assertNull(result, "Default implementation should return null");
    }

    /**
     * Test that AnnotationIntrospectorPair.findPrimaryCreator() delegates correctly.
     */
    @Test
    public void testAnnotationIntrospectorPairFindPrimaryCreator() {
        AnnotationIntrospector primary = mock(AnnotationIntrospector.class);
        AnnotationIntrospector secondary = mock(AnnotationIntrospector.class);
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        MapperConfig<?> config = mock(MapperConfig.class);
        AnnotatedClass valueClass = mock(AnnotatedClass.class);
        List<PotentialCreator> constructors = new ArrayList<>();
        List<PotentialCreator> factories = new ArrayList<>();

        PotentialCreator expectedCreator = mock(PotentialCreator.class);

        // Test when primary returns a value
        when(primary.findPrimaryCreator(config, valueClass, constructors, factories))
            .thenReturn(expectedCreator);

        PotentialCreator result = pair.findPrimaryCreator(
            config, valueClass, constructors, factories);

        assertEquals(expectedCreator, result);
        verify(secondary, never()).findPrimaryCreator(any(), any(), any(), any());

        // Test when primary returns null, secondary should be called
        reset(primary, secondary);
        when(primary.findPrimaryCreator(config, valueClass, constructors, factories))
            .thenReturn(null);
        when(secondary.findPrimaryCreator(config, valueClass, constructors, factories))
            .thenReturn(expectedCreator);

        result = pair.findPrimaryCreator(
            config, valueClass, constructors, factories);

        assertEquals(expectedCreator, result);
        verify(secondary).findPrimaryCreator(config, valueClass, constructors, factories);
    }

    /**
     * Test PotentialCreator.isAnnotated() method.
     */
    @Test
    public void testPotentialCreatorIsAnnotated() {
        AnnotatedWithParams mockCreator = mock(AnnotatedWithParams.class);
        when(mockCreator.getParameterCount()).thenReturn(0);

        // Creator with null mode (not annotated)
        PotentialCreator unannotated = new PotentialCreator(mockCreator, null);
        assertFalse(unannotated.isAnnotated(), "Should not be annotated when mode is null");

        // Creator with explicit mode (annotated)
        PotentialCreator annotated = new PotentialCreator(mockCreator, JsonCreator.Mode.PROPERTIES);
        assertTrue(annotated.isAnnotated(), "Should be annotated when mode is specified");

        PotentialCreator delegating = new PotentialCreator(mockCreator, JsonCreator.Mode.DELEGATING);
        assertTrue(delegating.isAnnotated(), "Should be annotated when mode is DELEGATING");
    }

    /**
     * Test PotentialCreator.creatorMode() and creatorModeOrDefault() methods.
     */
    @Test
    public void testPotentialCreatorCreatorMode() {
        AnnotatedWithParams mockCreator = mock(AnnotatedWithParams.class);
        when(mockCreator.getParameterCount()).thenReturn(0);

        // Creator with null mode
        PotentialCreator unannotated = new PotentialCreator(mockCreator, null);
        assertEquals(JsonCreator.Mode.DEFAULT, unannotated.creatorMode(),
            "creatorMode() should return DEFAULT when constructed with null");
        assertEquals(JsonCreator.Mode.DEFAULT, unannotated.creatorModeOrDefault(),
            "creatorModeOrDefault() should return DEFAULT");

        // Creator with explicit PROPERTIES mode
        PotentialCreator properties = new PotentialCreator(mockCreator, JsonCreator.Mode.PROPERTIES);
        assertEquals(JsonCreator.Mode.PROPERTIES, properties.creatorMode());
        assertEquals(JsonCreator.Mode.PROPERTIES, properties.creatorModeOrDefault());

        // Creator with explicit DELEGATING mode
        PotentialCreator delegating = new PotentialCreator(mockCreator, JsonCreator.Mode.DELEGATING);
        assertEquals(JsonCreator.Mode.DELEGATING, delegating.creatorMode());
        assertEquals(JsonCreator.Mode.DELEGATING, delegating.creatorModeOrDefault());
    }

    /**
     * Test PotentialCreator.overrideMode() method.
     */
    @Test
    public void testPotentialCreatorOverrideMode() {
        AnnotatedWithParams mockCreator = mock(AnnotatedWithParams.class);
        when(mockCreator.getParameterCount()).thenReturn(0);

        PotentialCreator creator = new PotentialCreator(mockCreator, null);

        // Initially should be DEFAULT
        assertEquals(JsonCreator.Mode.DEFAULT, creator.creatorMode());

        // Override to PROPERTIES
        PotentialCreator result = creator.overrideMode(JsonCreator.Mode.PROPERTIES);
        assertSame(creator, result, "overrideMode should return this for chaining");
        assertEquals(JsonCreator.Mode.PROPERTIES, creator.creatorMode());

        // Override to DELEGATING
        creator.overrideMode(JsonCreator.Mode.DELEGATING);
        assertEquals(JsonCreator.Mode.DELEGATING, creator.creatorMode());
    }

    /**
     * Test PotentialCreator.introspectParamNames() with zero parameters.
     */
    @Test
    public void testIntrospectParamNamesZeroParams() {
        AnnotatedWithParams mockCreator = mock(AnnotatedWithParams.class);
        when(mockCreator.getParameterCount()).thenReturn(0);

        PotentialCreator creator = new PotentialCreator(mockCreator, null);
        MapperConfig<?> config = mock(MapperConfig.class);

        PotentialCreator result = creator.introspectParamNames(config);

        assertSame(creator, result, "Should return this for chaining");
        assertEquals(0, creator.paramCount());
    }

    /**
     * Test PotentialCreator.introspectParamNames() with parameters and annotation introspector.
     * This test covers both implicit and explicit name paths.
     */
    @Test
    public void testIntrospectParamNamesWithParameters() {
        AnnotatedWithParams mockCreator = mock(AnnotatedWithParams.class);
        AnnotatedParameter mockParam1 = mock(AnnotatedParameter.class);
        AnnotatedParameter mockParam2 = mock(AnnotatedParameter.class);

        when(mockCreator.getParameterCount()).thenReturn(2);
        when(mockCreator.getParameter(0)).thenReturn(mockParam1);
        when(mockCreator.getParameter(1)).thenReturn(mockParam2);

        PotentialCreator creator = new PotentialCreator(mockCreator, null);

        AnnotationIntrospector mockIntrospector = mock(AnnotationIntrospector.class);
        MapperConfig<?> config = mock(MapperConfig.class);
        when(config.getAnnotationIntrospector()).thenReturn(mockIntrospector);

        // Setup implicit names
        when(mockIntrospector.findImplicitPropertyName(mockParam1)).thenReturn("param1");
        when(mockIntrospector.findImplicitPropertyName(mockParam2)).thenReturn("param2");

        // Setup explicit names - this covers the uncovered line for explicit name setting
        when(mockIntrospector.findNameForDeserialization(mockParam1))
            .thenReturn(PropertyName.construct("explicit1"));
        when(mockIntrospector.findNameForDeserialization(mockParam2))
            .thenReturn(null);

        PotentialCreator result = creator.introspectParamNames(config);

        assertSame(creator, result, "Should return this for chaining");

        // Verify implicit names
        assertEquals("param1", creator.implicitNameSimple(0));
        assertEquals("param2", creator.implicitNameSimple(1));

        // Verify explicit names
        assertEquals("explicit1", creator.explicitName(0).getSimpleName());
        assertNull(creator.explicitName(1), "Second param should have no explicit name");

        // Verify hasExplicitNames
        assertTrue(creator.hasExplicitNames());

        // Verify hasNameFor
        assertTrue(creator.hasNameFor(0));
        assertTrue(creator.hasNameFor(1));
    }

    /**
     * Test PotentialCreator.introspectParamNames() is idempotent.
     * Fixed version that properly verifies idempotency without clearing mock behavior.
     */
    @Test
    public void testIntrospectParamNamesIdempotent() {
        AnnotatedWithParams mockCreator = mock(AnnotatedWithParams.class);
        AnnotatedParameter mockParam = mock(AnnotatedParameter.class);

        when(mockCreator.getParameterCount()).thenReturn(1);
        when(mockCreator.getParameter(0)).thenReturn(mockParam);

        PotentialCreator creator = new PotentialCreator(mockCreator, null);

        AnnotationIntrospector mockIntrospector = mock(AnnotationIntrospector.class);
        MapperConfig<?> config = mock(MapperConfig.class);
        when(config.getAnnotationIntrospector()).thenReturn(mockIntrospector);
        when(mockIntrospector.findImplicitPropertyName(mockParam)).thenReturn("param1");

        // First call
        creator.introspectParamNames(config);

        // Second call should not invoke introspector again (idempotent)
        creator.introspectParamNames(config);

        // Verify introspector was only called once
        verify(mockIntrospector, times(1)).findImplicitPropertyName(mockParam);
    }

    /**
     * Test PotentialCreator with empty implicit name (should not be set).
