 * and PotentialCreator enhancements.
 */
public class PrimaryCreatorExtensionTest {

    /**
     * Test that AnnotationIntrospector.findPrimaryCreator() returns null by default.
     */
    @Test
    public void testFindPrimaryCreatorDefaultImplementation() {
        AnnotationIntrospector introspector = new AnnotationIntrospector() {
            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        MapperConfig<?> config = mock(MapperConfig.class);
        AnnotatedClass valueClass = mock(AnnotatedClass.class);
        List<PotentialCreator> constructors = new ArrayList<>();
        List<PotentialCreator> factories = new ArrayList<>();

        PotentialCreator result = introspector.findPrimaryCreator(
            config, valueClass, constructors, factories);

        assertNull(result, "Default implementation should return null");
    }

    /**
     * Test that AnnotationIntrospectorPair.findPrimaryCreator() delegates correctly.
     */
    @Test
    public void testAnnotationIntrospectorPairFindPrimaryCreator() {
        AnnotationIntrospector primary = mock(AnnotationIntrospector.class);
        AnnotationIntrospector secondary = mock(AnnotationIntrospector.class);
        AnnotationIntrospectorPair pair = new AnnotationIntrospectorPair(primary, secondary);

        MapperConfig<?> config = mock(MapperConfig.class);
        AnnotatedClass valueClass = mock(AnnotatedClass.class);
        List<PotentialCreator> constructors = new ArrayList<>();
        List<PotentialCreator> factories = new ArrayList<>();

        PotentialCreator expectedCreator = mock(PotentialCreator.class);

        // Test when primary returns a value
        when(primary.findPrimaryCreator(config, valueClass, constructors, factories))
            .thenReturn(expectedCreator);

        PotentialCreator result = pair.findPrimaryCreator(
            config, valueClass, constructors, factories);

        assertEquals(expectedCreator, result);
        verify(secondary, never()).findPrimaryCreator(any(), any(), any(), any());

        // Test when primary returns null, secondary should be called
        reset(primary, secondary);
        when(primary.findPrimaryCreator(config, valueClass, constructors, factories))
            .thenReturn(null);
        when(secondary.findPrimaryCreator(config, valueClass, constructors, factories))
            .thenReturn(expectedCreator);

        result = pair.findPrimaryCreator(
            config, valueClass, constructors, factories);

        assertEquals(expectedCreator, result);
        verify(secondary).findPrimaryCreator(config, valueClass, constructors, factories);
    }

