        PotentialCreator unannotated = new PotentialCreator(mockCreator, null);
        assertFalse(unannotated.isAnnotated(), "Should not be annotated when mode is null");

        // Creator with explicit mode (annotated)
        PotentialCreator annotated = new PotentialCreator(mockCreator, JsonCreator.Mode.PROPERTIES);
        assertTrue(annotated.isAnnotated(), "Should be annotated when mode is specified");

        PotentialCreator delegating = new PotentialCreator(mockCreator, JsonCreator.Mode.DELEGATING);
        assertTrue(delegating.isAnnotated(), "Should be annotated when mode is DELEGATING");
