        PotentialCreator unannotated = new PotentialCreator(mockCreator, null);
        assertEquals(JsonCreator.Mode.DEFAULT, unannotated.creatorMode(),
            "creatorMode() should return DEFAULT when constructed with null");
        assertEquals(JsonCreator.Mode.DEFAULT, unannotated.creatorModeOrDefault(),
            "creatorModeOrDefault() should return DEFAULT");

        // Creator with explicit PROPERTIES mode
        PotentialCreator properties = new PotentialCreator(mockCreator, JsonCreator.Mode.PROPERTIES);
        assertEquals(JsonCreator.Mode.PROPERTIES, properties.creatorMode());
        assertEquals(JsonCreator.Mode.PROPERTIES, properties.creatorModeOrDefault());

