package com.fasterxml.jackson.databind.introspect;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.PropertyName;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Test for PropertyName.merge() and AnnotationIntrospectorPair methods
 * that use it (Issue #4364)
 */
public class PropertyNameMerge4364Test {

    // ============================================================
    // Tests for PropertyName.merge()
    // ============================================================

    @Test
    public void testPropertyNameMergeBothNull() {
        assertNull(PropertyName.merge(null, null));
    }

    @Test
    public void testPropertyNameMergeFirstNull() {
        PropertyName name2 = PropertyName.construct("name", "ns");
        assertSame(name2, PropertyName.merge(null, name2));
    }

    @Test
    public void testPropertyNameMergeSecondNull() {
        PropertyName name1 = PropertyName.construct("name", "ns");
        assertSame(name1, PropertyName.merge(name1, null));
    }

    @Test
    public void testPropertyNameMergeFirstTakesPrecedence() {
        PropertyName name1 = PropertyName.construct("name1", "ns1");
        PropertyName name2 = PropertyName.construct("name2", "ns2");

        PropertyName merged = PropertyName.merge(name1, name2);
        assertEquals("name1", merged.getSimpleName());
        assertEquals("ns1", merged.getNamespace());
        // Should return name1 instance if no changes needed
        assertSame(name1, merged);
    }

    @Test
    public void testPropertyNameMergeEmptySimpleNameFromFirst() {
        PropertyName name1 = PropertyName.construct("", "ns1");
        PropertyName name2 = PropertyName.construct("name2", "ns2");

        PropertyName merged = PropertyName.merge(name1, name2);
