package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospectorPair;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotatedClass;
import com.fasterxml.jackson.databind.introspect.AnnotatedField;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.core.Version;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for PropertyName.merge() method and its integration
 * with AnnotationIntrospectorPair (issue #4364).
 */
public class PropertyNameMergeTest {

    @Test
    public void testMergeWithNullName1() {
        PropertyName name1 = null;
        PropertyName name2 = PropertyName.construct("test", "ns");
        PropertyName result = PropertyName.merge(name1, name2);
        assertEquals(name2, result);
    }

    @Test
    public void testMergeWithNullName2() {
        PropertyName name1 = PropertyName.construct("test", "ns");
        PropertyName name2 = null;
        PropertyName result = PropertyName.merge(name1, name2);
        assertEquals(name1, result);
    }

    @Test
    public void testMergeWithBothNull() {
        PropertyName result = PropertyName.merge(null, null);
        assertNull(result);
    }

    @Test
    public void testMergeName1TakesPrecedenceForSimpleName() {
        PropertyName name1 = PropertyName.construct("primary", "ns1");
        PropertyName name2 = PropertyName.construct("secondary", "ns2");
        PropertyName result = PropertyName.merge(name1, name2);
        assertEquals("primary", result.getSimpleName());
        assertEquals("ns1", result.getNamespace());
    }

    @Test
    public void testMergeName1EmptySimpleNameUsesName2() {
        PropertyName name1 = PropertyName.construct("", "ns1");
        PropertyName name2 = PropertyName.construct("secondary", "ns2");
        PropertyName result = PropertyName.merge(name1, name2);
        assertEquals("secondary", result.getSimpleName());
        assertEquals("ns1", result.getNamespace());
    }

    @Test
    public void testMergeName1EmptyNamespaceUsesName2() {
        PropertyName name1 = PropertyName.construct("primary", "");
        PropertyName name2 = PropertyName.construct("secondary", "ns2");
        PropertyName result = PropertyName.merge(name1, name2);
        assertEquals("primary", result.getSimpleName());
        assertEquals("ns2", result.getNamespace());
    }

    @Test
    public void testMergeName1NullNamespaceUsesName2() {
        PropertyName name1 = PropertyName.construct("primary", null);
        PropertyName name2 = PropertyName.construct("secondary", "ns2");
        PropertyName result = PropertyName.merge(name1, name2);
        assertEquals("primary", result.getSimpleName());
        assertEquals("ns2", result.getNamespace());
    }

    @Test
    public void testMergeBothEmptyUsesName2() {
        PropertyName name1 = PropertyName.construct("", "");
        PropertyName name2 = PropertyName.construct("secondary", "ns2");
        PropertyName result = PropertyName.merge(name1, name2);
        assertEquals("secondary", result.getSimpleName());
        assertEquals("ns2", result.getNamespace());
    }

    @Test
    public void testMergeReturnsName1UnchangedWhenNoMergeNeeded() {
        PropertyName name1 = PropertyName.construct("test", "ns");
        PropertyName name2 = PropertyName.construct("other", "otherNs");
        PropertyName result = PropertyName.merge(name1, name2);
        assertSame(name1, result);
    }

    @Test
    public void testMergeReturnsName2UnchangedWhenName1IsEmpty() {
        PropertyName name1 = PropertyName.construct("", "");
        PropertyName name2 = PropertyName.construct("test", "ns");
