            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);

        List<JsonNode> foundParents = rootNode.findParents("target");

        // Optimized: Check for empty instead of strictly null to accommodate child node 
        // implementations that may return an empty list instead of null.
        assertTrue("findParents should be empty when no matches", foundParents == null || foundParents.isEmpty());
    }

    @Test
    public void testFindValuesDeeplyNestedStructure() throws Exception {
        // Test with deeply nested structure to ensure recursion works correctly
        // and the 'else' branch (recursive descent) is covered for non-matching keys
        String json = "{" +
            "\"target\": \"level0\"," +
            "\"level1\": {" +
            "  \"target\": \"level1\"," +
            "  \"level2\": {" +
            "    \"target\": \"level2\"," +
            "    \"level3\": {" +
            "      \"target\": \"level3\"" +
            "    }" +
            "  }" +
            "}," +
            "\"sibling\": {" +
            "  \"target\": \"sibling\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);

        List<JsonNode> foundValues = rootNode.findValues("target");

        assertNotNull("findValues should not return null for deeply nested structure", foundValues);
        assertEquals("Should find 5 target properties at different levels", 5, foundValues.size());

        // Verify content (order depends on insertion order in ObjectNode)
        List<String> texts = new ArrayList<>();
        for (JsonNode node : foundValues) {
            texts.add(node.asText());
        }

        assertTrue("Should contain level0", texts.contains("level0"));
        assertTrue("Should contain level1", texts.contains("level1"));
        assertTrue("Should contain level2", texts.contains("level2"));
        assertTrue("Should contain level3", texts.contains("level3"));
        assertTrue("Should contain sibling", texts.contains("sibling"));
    }

    @Test
    public void testFindParentsRecursiveDescent() throws Exception {
        // Specifically tests the 'else' branch in findParents where key does not match
        // but children need to be searched.
        String json = "{" +
            "\"wrapper1\": {" +
            "  \"target\": \"inside1\"" +
            "}," +
            "\"wrapper2\": {" +
            "  \"target\": \"inside2\"" +
            "}" +
            "}";

        JsonNode rootNode = mapper.readTree(json);

        // Root does not have "target" directly, so 'else' branch is taken for all children
        List<JsonNode> foundParents = rootNode.findParents("target");

        assertNotNull("findParents should find parents in nested objects", foundParents);
        assertEquals("Should find 2 parent nodes (wrapper1 and wrapper2)", 2, foundParents.size());

        // Both parents should be the wrapper objects
        for (JsonNode parent : foundParents) {
            assertTrue("Parent should be object", parent.isObject());
            // Ensure they are not the root
            assertNotSame("Parent should not be root", rootNode, parent);
        }
    }
}

