        MyBean result = mapper.readValue("[{\"value\": \"test\"}]", MyBean.class);
        assertEquals("test", result.value);
    }

    @Test
    public void testDeserializeBeanFromDeeplyNestedArrayWithUnwrapShouldFail() throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(DeserializationFeature.UNWRAP_SINGLE_VALUE_ARRAYS);

        // Covers BeanDeserializer._deserializeFromArray fix (DoS prevention check using unwrappedToken)
        // Before fix, p.nextToken() was called twice, potentially skipping the check or causing errors.
        try {
