package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.JsonPointer;
import com.fasterxml.jackson.databind.JsonNode;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Test class for verifying the behavior of ObjectNode.withObject(String) method
 * after the patch that allows it to accept both JsonPointer expressions and 
 * simple property names (similar to withArray(String)).
 */
public class ObjectNodeWithObjectStringTest {

    @Test
    public void testWithObjectWithSimplePropertyName() {
        ObjectNode root = JsonNodeFactory.instance.objectNode();

        // Test with simple property name (not a JsonPointer - no leading '/')
        ObjectNode child = root.withObject("propertyName");

        assertNotNull("withObject should return non-null ObjectNode", child);
