package com.fasterxml.jackson.databind.type;

import org.junit.Test;
import static org.junit.Assert.*;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;

/**
 * Unit tests for TypeParser guardrails added in issue #4011.
 * Tests the MAX_TYPE_LENGTH and MAX_TYPE_NESTING limits.
 */
public class TypeParserGuardrailsTest {

    @Test
    public void testNormalTypeParsing() throws Exception {
        TypeFactory factory = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(factory);

        // Test normal type parsing still works
        JavaType type = parser.parse("java.util.Map<java.lang.String, java.lang.Integer>");
        assertNotNull(type);
        assertEquals("java.util.Map", type.getRawClass().getName());
    }

    @Test
    public void testTypeLengthExceedsMax() throws Exception {
        TypeFactory factory = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(factory);

        // Create a type string that exceeds MAX_TYPE_LENGTH (64,000)
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.Map<java.lang.String,");
        while (sb.length() < TypeParser.MAX_TYPE_LENGTH + 100) {
            sb.append("java.lang.String,");
        }
        sb.append("java.lang.Integer>");

        String longType = sb.toString();

        try {
            parser.parse(longType);
            fail("Expected IllegalArgumentException for type string exceeding max length");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention 'too long': " + e.getMessage(), 
                       e.getMessage().contains("too long"));
            assertTrue("Error message should mention max length 64000: " + e.getMessage(), 
                       e.getMessage().contains("64000"));
            // Since input > 64000, it is definitely > 1000, so truncation should be mentioned
            // This validates the _quoteTruncated logic in the length check
            assertTrue("Error message should contain truncation indicator for long input: " + e.getMessage(),
                       e.getMessage().contains("truncated"));
        }
    }

    @Test
    public void testTypeNestingExceedsMax() throws Exception {
        TypeFactory factory = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(factory);

        // Create a deeply nested type that exceeds MAX_TYPE_NESTING (1000)
        StringBuilder sb = new StringBuilder();
        sb.append("java.util.List<");
        for (int i = 0; i < TypeParser.MAX_TYPE_NESTING + 10; i++) {
            sb.append("java.util.List<");
        }
        sb.append("java.lang.String");
        for (int i = 0; i < TypeParser.MAX_TYPE_NESTING + 10; i++) {
            sb.append(">");
        }

        String nestedType = sb.toString();

        try {
            parser.parse(nestedType);
            fail("Expected IllegalArgumentException for type nesting exceeding max");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention 'too deeply nested': " + e.getMessage(), 
                       e.getMessage().contains("too deeply nested"));
            assertTrue("Error message should mention max nesting 1000: " + e.getMessage(), 
                       e.getMessage().contains("1000"));
            // The input string is very long (>1000 chars), so _problem -> _quoteTruncated should trigger
            assertTrue("Error message should contain truncation indicator for long input: " + e.getMessage(),
                       e.getMessage().contains("truncated"));
        }
    }

    @Test
    public void testUnexpectedTokensWithTruncation() throws Exception {
        TypeFactory factory = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(factory);

        // Create a valid type followed by garbage, total length > 1000 to test truncation in _problem
        // This specifically covers the uncovered line: if (tokens.hasMoreTokens()) { throw _problem... }
        // We use ',' as a separator to ensure the tokenizer correctly splits the valid type from the garbage.
        // Using space previously caused 'findClass' to consume the entire string as a class name in some environments,
        // preventing the 'Unexpected tokens' check from being reached.
        StringBuilder sb = new StringBuilder();
        sb.append("java.lang.String,");
        while (sb.length() < 1100) {
            sb.append("garbage");
        }

        String invalidType = sb.toString();

        try {
            parser.parse(invalidType);
            fail("Expected IllegalArgumentException for unexpected tokens");
        } catch (IllegalArgumentException e) {
            assertTrue("Error message should mention 'Unexpected tokens': " + e.getMessage(),
                       e.getMessage().contains("Unexpected tokens"));
            // Input > 1000 chars, so _quoteTruncated should trigger in _problem
            assertTrue("Error message should contain truncation indicator: " + e.getMessage(),
                       e.getMessage().contains("truncated"));
        }
    }

    @Test
    public void testTypeLengthAtBoundary() throws Exception {
        TypeFactory factory = TypeFactory.defaultInstance();
        TypeParser parser = new TypeParser(factory);

        // Create a type string at exactly MAX_TYPE_LENGTH - should not fail due to length
        StringBuilder sb = new StringBuilder();
        sb.append("java.lang.String");
        while (sb.length() < TypeParser.MAX_TYPE_LENGTH - 100) {
            sb.append(",");
        }

        String boundaryType = sb.toString();

        // This may fail for other reasons (invalid type/unexpected tokens), but not for length
        try {
            parser.parse(boundaryType);
        } catch (IllegalArgumentException e) {
            // Should not fail due to length check
            assertFalse("Should not fail due to length at boundary: " + e.getMessage(), 
                        e.getMessage().contains("too long"));
        }
    }

    @Test
    public void testConstantsAreAccessible() throws Exception {
        // Verify the constants are accessible and have expected values
        assertEquals("MAX_TYPE_LENGTH should be 64000", 64_000, TypeParser.MAX_TYPE_LENGTH);
        assertEquals("MAX_TYPE_NESTING should be 1000", 1000, TypeParser.MAX_TYPE_NESTING);
    }
}

