        assertTrue(creator.isAnnotated());
        assertEquals(JsonCreator.Mode.PROPERTIES, creator.creatorMode());
        assertEquals(JsonCreator.Mode.PROPERTIES, creator.creatorModeOrDefault());
    }

    @Test
