        // Given: PotentialCreator with null mode (defaults to DEFAULT)
        AnnotatedWithParams mockCreator = Mockito.mock(AnnotatedWithParams.class);
        when(mockCreator.getParameterCount()).thenReturn(0);
        PotentialCreator creator = new PotentialCreator(mockCreator, null);

        // When: Overriding mode to DELEGATING
