    @Test
    public void testFindPrimaryCreatorWithFactories() {
        // Given: Custom AnnotationIntrospector that prefers factory methods
        AnnotationIntrospector customIntrospector = new AnnotationIntrospector() {
            @Override
            public PotentialCreator findPrimaryCreator(MapperConfig<?> config,
                    AnnotatedClass valueClass,
                    List<PotentialCreator> declaredConstructors,
                    List<PotentialCreator> declaredFactories) {
                // Return first factory as primary if available
                if (!declaredFactories.isEmpty()) {
                    return declaredFactories.get(0);
                }
                return declaredConstructors.isEmpty() ? null : declaredConstructors.get(0);
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        MapperConfig<?> mockConfig = Mockito.mock(MapperConfig.class);
        AnnotatedClass mockClass = Mockito.mock(AnnotatedClass.class);

        AnnotatedWithParams mockConstructor = Mockito.mock(AnnotatedWithParams.class);
        when(mockConstructor.getParameterCount()).thenReturn(1);
        PotentialCreator mockConstructorCreator = new PotentialCreator(mockConstructor, null);

        AnnotatedWithParams mockFactory = Mockito.mock(AnnotatedWithParams.class);
        when(mockFactory.getParameterCount()).thenReturn(1);
        PotentialCreator mockFactoryCreator = new PotentialCreator(mockFactory, null);

        List<PotentialCreator> constructors = Collections.singletonList(mockConstructorCreator);
        List<PotentialCreator> factories = Collections.singletonList(mockFactoryCreator);

        // When: Calling findPrimaryCreator with both constructors and factories
        PotentialCreator result = customIntrospector.findPrimaryCreator(
            mockConfig, mockClass, constructors, factories);

        // Then: Should return the factory (preferred)
        assertSame(mockFactoryCreator, result);
    }

