    @Test
    public void testFindPrimaryCreatorOverrideMode() {
        // Given: Custom AnnotationIntrospector that overrides mode
        AnnotationIntrospector customIntrospector = new AnnotationIntrospector() {
            @Override
            public PotentialCreator findPrimaryCreator(MapperConfig<?> config,
                    AnnotatedClass valueClass,
                    List<PotentialCreator> declaredConstructors,
                    List<PotentialCreator> declaredFactories) {
                if (declaredConstructors.isEmpty()) {
                    return null;
                }
                // Override mode to PROPERTIES
                return declaredConstructors.get(0).overrideMode(JsonCreator.Mode.PROPERTIES);
            }

            @Override
            public Version version() {
                return Version.unknownVersion();
            }
        };

        MapperConfig<?> mockConfig = Mockito.mock(MapperConfig.class);
        AnnotatedClass mockClass = Mockito.mock(AnnotatedClass.class);

        AnnotatedWithParams mockConstructor = Mockito.mock(AnnotatedWithParams.class);
        when(mockConstructor.getParameterCount()).thenReturn(1);
        PotentialCreator mockPotentialCreator = new PotentialCreator(mockConstructor, null);

        List<PotentialCreator> constructors = Collections.singletonList(mockPotentialCreator);
        List<PotentialCreator> factories = Collections.emptyList();

        // When: Calling findPrimaryCreator
        PotentialCreator result = customIntrospector.findPrimaryCreator(
            mockConfig, mockClass, constructors, factories);

        // Then: Should return creator with overridden mode
        assertSame(mockPotentialCreator, result);
        assertEquals(JsonCreator.Mode.PROPERTIES, result.creatorMode());
    }
